insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('digital-habits-awareness-log', 'Digital Habits Awareness Log', 'worksheet'::resource_kind, 'Tracks when and why a client reaches for a phone to spot the habit underneath the habit.', 'Help a client notice the triggers and payoffs behind automatic phone use.', array['Adults', 'Teens']::text[], 'One week', 'Screens are often reached for automatically, so this has a client log a handful of pickups each day: the moment before, the feeling driving it, and what happened right after. Patterns tend to surface within a few days, such as reaching for a phone whenever a task feels hard or a room goes quiet. Use the log to open a conversation about which habits the client wants to keep and which they would rather change, kept collaborative rather than a strict rule.', '[{"id": "f0", "type": "textarea", "label": "A moment today I picked up my phone without thinking"}, {"id": "f1", "type": "textarea", "label": "What I was feeling or avoiding right before"}, {"id": "f2", "type": "textarea", "label": "What I got out of it"}, {"id": "f3", "type": "textarea", "label": "A pickup I noticed was actually useful"}, {"id": "f4", "type": "textarea", "label": "One pattern I want to try changing"}]'::jsonb, array['habits', 'self-monitoring', 'screen time']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('forgiveness-process-worksheet', 'Forgiveness Process Worksheet', 'worksheet'::resource_kind, 'Walks a client through what forgiveness would and would not mean for a specific hurt.', 'Help a client sort out what letting go of a grudge would actually involve.', array['Adults']::text[], 'Full session', 'Forgiveness is often confused with excusing harm or reopening contact, so this worksheet separates the two: what the client would keep holding a person accountable for, and what they might set down for their own sake. There is no timeline attached and no expectation that the client reach a conclusion in one sitting. Some clients decide forgiveness is not the goal, and that is a legitimate place to land too.', '[{"id": "f0", "type": "textarea", "label": "The situation I am thinking about"}, {"id": "f1", "type": "textarea", "label": "What I am still angry or hurt about"}, {"id": "f2", "type": "textarea", "label": "What forgiving would not mean for me"}, {"id": "f3", "type": "textarea", "label": "What forgiving might mean for me, if anything"}, {"id": "f4", "type": "textarea", "label": "What I need before I could consider it"}]'::jsonb, array['forgiveness', 'processing', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('life-chapter-compass', 'Life Chapter Compass', 'worksheet'::resource_kind, 'Maps what a client wants to carry forward and leave behind during a major life change.', 'Give a client a structured way to think through a transition instead of just reacting to it.', array['Adults']::text[], '20 minutes', 'A move, a job change, a divorce or a new chapter of any kind can leave a client reacting to logistics without ever stepping back to ask what they actually want from the change. This worksheet has them name what from the old chapter is worth keeping, what they are relieved to leave, and what they hope the next chapter includes. Revisit it partway through the transition, since answers often shift once the change is underway.', '[{"id": "f0", "type": "textarea", "label": "The transition I am in or facing"}, {"id": "f1", "type": "textarea", "label": "What I want to carry forward from before"}, {"id": "f2", "type": "textarea", "label": "What I am relieved to be leaving behind"}, {"id": "f3", "type": "textarea", "label": "What I hope this next chapter includes"}, {"id": "f4", "type": "textarea", "label": "One small step that would move me toward it"}]'::jsonb, array['life transitions', 'values', 'goal setting']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('decision-fatigue-reset-sheet', 'Decision Fatigue Reset Sheet', 'worksheet'::resource_kind, 'Helps a client trim the number of daily decisions draining their energy.', 'Reduce the mental load of small daily decisions so a client has more energy for what matters.', array['Adults']::text[], '15 minutes', 'By the end of a long day, small decisions like what to eat or wear can feel as hard as the big ones, which is a common sign of decision fatigue rather than a personal failing. This sheet has a client list the decisions that repeat every day and pick a handful to simplify or automate, such as a standing lunch rotation or laying out clothes the night before. The goal is fewer decisions overall, not more discipline.', '[{"id": "f0", "type": "textarea", "label": "Small decisions that repeat almost every day for me"}, {"id": "f1", "type": "textarea", "label": "One decision I could automate or simplify"}, {"id": "f2", "type": "textarea", "label": "One decision I could hand off or drop entirely"}, {"id": "f3", "type": "textarea", "label": "How I expect to feel with fewer decisions to make"}, {"id": "f4", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['decision fatigue', 'burnout', 'self-monitoring']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('work-life-boundary-map', 'Work-Life Boundary Map', 'worksheet'::resource_kind, 'Has a client draw where work currently bleeds into personal time and where they want a firmer line.', 'Give a client a visual starting point for setting boundaries around work hours.', array['Adults']::text[], '20 minutes', 'Many clients describe work as having no edges, checking messages at dinner or before sleep without quite deciding to. This map has a client sketch a typical day and mark where work currently spills over, then mark where they would like a firmer edge instead. Keep the first pass realistic rather than ideal, and revisit it once a new boundary has had a week or two to be tested.', '[{"id": "f0", "type": "textarea", "label": "A typical weekday, roughly hour by hour"}, {"id": "f1", "type": "textarea", "label": "Where work currently spills into personal time"}, {"id": "f2", "type": "textarea", "label": "One edge I want to hold more firmly"}, {"id": "f3", "type": "textarea", "label": "What might make that edge hard to hold"}, {"id": "f4", "type": "textarea", "label": "A support that would make it easier"}]'::jsonb, array['boundaries', 'burnout', 'work']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('mind-reading-evidence-check', 'Mind Reading Evidence Check', 'cbt'::resource_kind, 'Separates what a client actually knows about another person''s thoughts from what they assumed.', 'Help a client catch the thinking trap of assuming they know what someone else is thinking.', array['Adults', 'Teens']::text[], '10 minutes', 'Assuming another person''s thoughts without checking is one of the more common thinking traps, and it tends to run in one direction, usually toward a negative guess. This sheet has a client write the assumption, then list the actual evidence for it, and finally consider one or two other explanations that fit the same facts equally well. Over repeated use, clients often notice the gap between how confident the guess felt and how little evidence backed it.', '[{"id": "f0", "type": "textarea", "label": "What I assumed the other person was thinking"}, {"id": "f1", "type": "textarea", "label": "How confident I felt about that guess, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "The actual evidence I have for it"}, {"id": "f3", "type": "textarea", "label": "Another explanation that fits just as well"}, {"id": "f4", "type": "textarea", "label": "How I could check instead of guess"}]'::jsonb, array['thinking traps', 'core CBT', 'mind reading']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('fortune-telling-evidence-log', 'Fortune Telling Evidence Log', 'cbt'::resource_kind, 'Logs predicted outcomes against what actually happened to weaken the habit of forecasting doom.', 'Show a client the gap between predicted outcomes and what actually occurs.', array['Adults', 'Teens']::text[], 'One week', 'Predicting how a situation will go before it happens, almost always toward the worst case, keeps a client bracing for things that often do not occur. This log has them write a prediction before an event and the actual outcome afterward, side by side. Over a week or two the pattern usually becomes visible on the page itself, which tends to land better than being told the predictions are inaccurate.', '[{"id": "f0", "type": "textarea", "label": "The situation I am about to face"}, {"id": "f1", "type": "textarea", "label": "My prediction for how it will go"}, {"id": "f2", "type": "textarea", "label": "How confident I am in that prediction, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I notice comparing the two"}]'::jsonb, array['thinking traps', 'core CBT', 'prediction']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('labeling-language-swap', 'Labeling Language Swap', 'cbt'::resource_kind, 'Rewrites a global self-label as a specific, changeable behavior instead.', 'Help a client trade a fixed self-label for language that describes behavior, not identity.', array['Adults', 'Teens']::text[], '10 minutes', 'A single mistake can turn into a global label like calling oneself lazy or a failure, which tends to flatten a specific event into a fixed identity. This sheet has a client write the label they reached for, then rewrite it as a specific behavior in a specific moment instead. The rewrite is not meant to excuse the behavior, only to describe it in a way that leaves room for it to be different next time.', '[{"id": "f0", "type": "textarea", "label": "The label I called myself"}, {"id": "f1", "type": "textarea", "label": "The specific moment or behavior it was actually about"}, {"id": "f2", "type": "textarea", "label": "A description of that moment without the label attached"}, {"id": "f3", "type": "textarea", "label": "What I would want to do differently next time"}, {"id": "f4", "type": "textarea", "label": "One thing that label leaves out about me"}]'::jsonb, array['thinking traps', 'core CBT', 'self-talk']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('all-or-nothing-scale-practice', 'All-or-Nothing Scale Practice', 'cbt'::resource_kind, 'Has a client place a black-and-white judgment onto a 0 to 10 scale to find the middle ground.', 'Loosen all-or-nothing thinking by practicing a graded scale instead of two extremes.', array['Adults', 'Teens']::text[], '15 minutes', 'All-or-nothing thinking sorts a day, a relationship or a performance into only two bins, total success or total failure, which leaves no room for the middle ground where most of life actually happens. This practice has a client take a recent either-or judgment and place it on a 0 to 10 scale instead, then name what specifically earned it that number rather than a 0 or a 10. Repeating this with several judgments over a week usually starts to loosen the habit.', '[{"id": "f0", "type": "textarea", "label": "The all-or-nothing judgment I made"}, {"id": "f1", "type": "textarea", "label": "Where it lands on a 0 to 10 scale instead of two extremes"}, {"id": "f2", "type": "textarea", "label": "What specifically earned it that number"}, {"id": "f3", "type": "textarea", "label": "What would move it up one point"}, {"id": "f4", "type": "textarea", "label": "What I notice using a scale instead of two boxes"}]'::jsonb, array['thinking traps', 'core CBT', 'perspective']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('discounting-the-positive-log', 'Discounting the Positive Log', 'cbt'::resource_kind, 'Tracks moments a client waved off something good so the pattern becomes visible.', 'Help a client notice how often they dismiss positive events or feedback in the moment.', array['Adults']::text[], 'One week', 'Discounting the positive shows up as a quick mental edit, a compliment gets rephrased as politeness or a good outcome gets credited to luck, and it happens fast enough that clients rarely notice it in real time. This log asks a client to catch the moment right after it happens and write both the original event and the discount that followed. Reading the list back at the end of the week is often more persuasive than pointing it out in session.', '[{"id": "f0", "type": "textarea", "label": "Something good that happened or was said to me today"}, {"id": "f1", "type": "textarea", "label": "How I discounted or waved it off in the moment"}, {"id": "f2", "type": "textarea", "label": "What I would say if a friend discounted it that way"}, {"id": "f3", "type": "textarea", "label": "A version of the event without the discount attached"}, {"id": "f4", "type": "textarea", "label": "What I notice across the week''s entries"}]'::jsonb, array['thinking traps', 'core CBT', 'self-esteem']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('sailboat-in-the-storm-metaphor', 'Sailboat in the Storm Metaphor', 'act'::resource_kind, 'Uses a sailboat unable to control the weather to talk about steering toward values instead.', 'Give a client a metaphor for acting on values while difficult feelings are present, not after they pass.', array['Adults', 'Teens']::text[], '15 minutes', 'A sailor cannot control the wind or the waves, only the direction of the sail, and that image gives a client language for the difference between controlling a feeling and choosing a direction despite it. Talk through what the client''s current storm looks like and what steering toward values would look like inside it rather than after it clears. The point is not to calm the storm before moving; it is to move while it is happening.', '[{"id": "f0", "type": "textarea", "label": "What storm I am currently sailing through"}, {"id": "f1", "type": "textarea", "label": "What I have been trying to control that I cannot"}, {"id": "f2", "type": "textarea", "label": "The direction I actually want to steer toward"}, {"id": "f3", "type": "textarea", "label": "What steering that way would look like this week"}, {"id": "f4", "type": "textarea", "label": "What I can adjust, even if the storm does not calm"}]'::jsonb, array['metaphor', 'core ACT', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('man-in-the-hole-metaphor', 'Man in the Hole Metaphor', 'act'::resource_kind, 'Uses digging a bigger hole with the only tool on hand to talk about when a coping strategy stops working.', 'Help a client notice when a familiar coping strategy has become the thing digging the hole deeper.', array['Adults']::text[], '15 minutes', 'A person stuck in a hole with only a shovel keeps digging because it is the only tool they have, even though digging makes the hole deeper, and the metaphor gives a client a nonjudgmental way to talk about a coping strategy that no longer helps. Name the strategy together, what it was meant to solve, and what putting the shovel down and trying something else might look like. This works best held lightly rather than as a verdict on the client.', '[{"id": "f0", "type": "textarea", "label": "The hole I feel stuck in"}, {"id": "f1", "type": "textarea", "label": "The shovel, or strategy, I keep reaching for"}, {"id": "f2", "type": "textarea", "label": "What that strategy was originally trying to solve"}, {"id": "f3", "type": "textarea", "label": "What putting the shovel down might look like"}, {"id": "f4", "type": "textarea", "label": "A different tool I could try instead"}]'::jsonb, array['metaphor', 'core ACT', 'struggle']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('career-transition-values-sheet', 'Career Transition Values Sheet', 'act'::resource_kind, 'Grounds a career change in values instead of only in salary or title.', 'Help a client weigh a career decision against what actually matters to them.', array['Adults']::text[], '20 minutes', 'A career change is often framed purely in terms of salary, title or prestige, which can leave a client feeling unsettled even after landing an objectively good offer. This sheet has a client name the values they want their work to serve, then hold each option they are weighing up against those values rather than against each other directly. It is meant to sit alongside practical factors, not replace them.', '[{"id": "f0", "type": "textarea", "label": "The career decision or transition in front of me"}, {"id": "f1", "type": "textarea", "label": "The values I want my work to serve"}, {"id": "f2", "type": "textarea", "label": "How each option lines up with those values"}, {"id": "f3", "type": "textarea", "label": "What a purely practical decision might miss"}, {"id": "f4", "type": "textarea", "label": "What I am leaning toward and why"}]'::jsonb, array['values', 'core ACT', 'life transitions']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('retirement-identity-values-practice', 'Retirement Identity Values Practice', 'act'::resource_kind, 'Helps a client separate their sense of self from a job title they are about to lose.', 'Support a client in finding identity and values beyond a role that is ending.', array['Adults']::text[], 'Full session', 'Retirement can remove a role a client has organized much of their identity around for decades, and the loss of structure and purpose often surprises people who expected only to feel relief. This practice has a client name what the role gave them beyond a paycheck, such as purpose, contact with people or a sense of competence, and then explore other ways those same needs could be met going forward. Go slowly; this can bring up grief alongside relief.', '[{"id": "f0", "type": "textarea", "label": "What my work role gave me beyond income"}, {"id": "f1", "type": "textarea", "label": "What I am relieved to be leaving behind"}, {"id": "f2", "type": "textarea", "label": "What I am grieving or unsure about losing"}, {"id": "f3", "type": "textarea", "label": "Another way I could meet that same need going forward"}, {"id": "f4", "type": "textarea", "label": "What I want this next chapter to be about"}]'::jsonb, array['values', 'core ACT', 'life transitions']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('forgiveness-as-willingness-practice', 'Forgiveness as Willingness Practice', 'act'::resource_kind, 'Reframes forgiveness as a willingness to stop carrying a struggle rather than a verdict about another person.', 'Help a client consider forgiveness as an act of willingness rather than a judgment they owe someone else.', array['Adults']::text[], '20 minutes', 'Forgiveness debates often get stuck on whether the other person deserves it, which can keep a client carrying a struggle indefinitely while waiting for an answer that may never come. This practice reframes forgiveness as a willingness question aimed at the client''s own life: am I willing to stop carrying this, for my own sake, regardless of what the other person deserves. There is no requirement to reach a yes, only to look at the question honestly.', '[{"id": "f0", "type": "textarea", "label": "What I am carrying that relates to this person"}, {"id": "f1", "type": "textarea", "label": "What carrying it is costing me"}, {"id": "f2", "type": "textarea", "label": "Whether willingness to set it down feels possible right now"}, {"id": "f3", "type": "textarea", "label": "What setting it down would and would not mean"}, {"id": "f4", "type": "textarea", "label": "One value it would free me up to move toward"}]'::jsonb, array['forgiveness', 'core ACT', 'willingness']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('choosing-acceptance-again-practice', 'Choosing Acceptance Again Practice', 'dbt'::resource_kind, 'Practices the repeated choice to turn toward acceptance of a fact a client cannot change.', 'Give a client a concrete way to practice choosing acceptance again and again, not just once.', array['Adults', 'Teens']::text[], '10 minutes', 'Turning the mind is less a single decision than a repeated one, like standing at a fork in the road and choosing the accepting path over and over as the mind wanders back toward fighting a fact. This card has a client name a fact they are working on accepting and practice noticing the moment they turn away from it, then gently turn back. It rarely happens once and is complete; expect it to be a return, not a finish line.', '[{"id": "f0", "type": "textarea", "label": "The fact I am practicing accepting"}, {"id": "f1", "type": "textarea", "label": "A moment today I turned away from accepting it"}, {"id": "f2", "type": "textarea", "label": "What turning back toward acceptance looked like"}, {"id": "f3", "type": "textarea", "label": "How many times I noticed the choice today"}, {"id": "f4", "type": "textarea", "label": "What made turning back easier or harder"}]'::jsonb, array['acceptance', 'core DBT', 'willingness']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('building-a-life-worth-living-plan', 'Building a Life Worth Living Plan', 'dbt'::resource_kind, 'Has a client sketch what more of their life would need to include to feel worth living day to day.', 'Give a client a concrete, ongoing picture of the life they are working toward, not just the crisis they are managing.', array['Adults']::text[], 'Full session', 'Skills work can end up entirely focused on managing crises, which leaves little room to talk about what the client actually wants their life to include. This plan has a client name what currently makes life worth living, what is missing, and one step toward adding more of it in. If low points or thoughts of self-harm come up while building this plan, complete this in session, and name that 988 can be called or texted anytime the client needs support between sessions.', '[{"id": "f0", "type": "textarea", "label": "What currently makes my life feel worth living"}, {"id": "f1", "type": "textarea", "label": "What is missing that I wish were there"}, {"id": "f2", "type": "textarea", "label": "One value or activity I want more of in my life"}, {"id": "f3", "type": "textarea", "label": "A small step toward adding it in this month"}, {"id": "f4", "type": "textarea", "label": "Who or what I can lean on along the way"}]'::jsonb, array['core DBT', 'values', 'crisis']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('willingness-vs-willfulness-check', 'Willingness vs Willfulness Check', 'dbt'::resource_kind, 'Helps a client tell the difference between digging in against reality and cooperating with it.', 'Help a client notice when they are fighting a situation rather than working with it.', array['Adults']::text[], '10 minutes', 'Willfulness looks like refusing to do what is needed, crossing arms and insisting reality should be different, while willingness looks like doing what the moment calls for even when it is unwelcome. This check has a client notice a current stuck point and ask which stance they are in, then consider what one willing action might look like even without feeling ready. Naming the stance out loud often loosens it on its own.', '[{"id": "f0", "type": "textarea", "label": "The situation I feel stuck in"}, {"id": "f1", "type": "textarea", "label": "Signs I am in a willful stance right now"}, {"id": "f2", "type": "textarea", "label": "What willingness would look like here instead"}, {"id": "f3", "type": "textarea", "label": "One small willing action I could take"}, {"id": "f4", "type": "textarea", "label": "What is making willingness hard right now"}]'::jsonb, array['core DBT', 'acceptance', 'willingness']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-card', 'IMPROVE the Moment Card', 'dbt'::resource_kind, 'A pocket card of ways to make a hard moment more bearable without needing it to be over.', 'Give a client a quick menu of ways to get through a hard moment rather than escape it.', array['Adults', 'Teens']::text[], 'Five minutes', 'Some moments cannot be shortened or avoided, only gotten through, and this card offers a short menu of ways to make that getting-through a little more bearable: imagery, meaning, a brief prayer or reflection, relaxing the body, one thing at a time, a short vacation from the problem, and encouragement to oneself. A client picks whichever one or two fit the moment rather than working through the whole list in order.', '[{"id": "f0", "type": "textarea", "label": "The hard moment I am in"}, {"id": "f1", "type": "textarea", "label": "Which idea on the card I am drawn to right now"}, {"id": "f2", "type": "textarea", "label": "What using it looked like"}, {"id": "f3", "type": "textarea", "label": "How the moment felt afterward, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "Which idea I want to remember for next time"}]'::jsonb, array['distress tolerance', 'core DBT', 'skills']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('observe-describe-participate-practice', 'Observe Describe Participate Practice', 'dbt'::resource_kind, 'Practices the three mindfulness what-skills in a short daily sequence.', 'Build fluency with the observe, describe and participate skills as a short daily sequence.', array['Adults', 'Teens']::text[], '10 minutes', 'Observing, describing and participating are the three what-skills of mindfulness, and practicing them in a fixed short sequence, first just noticing, then putting words to it, then stepping fully into the activity, helps them become more automatic over time. This card walks a client through the sequence with any ordinary moment, a meal, a walk, a conversation. Keep it brief; a minute of each step is enough to build the habit.', '[{"id": "f0", "type": "textarea", "label": "What I am observing right now, without judging it"}, {"id": "f1", "type": "textarea", "label": "How I would describe it in plain words"}, {"id": "f2", "type": "textarea", "label": "What fully participating in this moment looks like"}, {"id": "f3", "type": "textarea", "label": "What pulled my attention away, if anything"}, {"id": "f4", "type": "textarea", "label": "How this felt compared with going on autopilot"}]'::jsonb, array['mindfulness', 'core DBT', 'skills']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('blended-family-roles-sheet', 'Blended Family Roles Sheet', 'couples'::resource_kind, 'Has both partners name what role each wants with the other''s children before conflicts force the question.', 'Give a blended family couple a shared, explicit picture of each partner''s role instead of an assumed one.', array['Couples']::text[], '20 minutes', 'Blended families often run into conflict when partners have never actually discussed what role a stepparent should play with the other''s children, discipline especially, and each partner has been operating on an unstated assumption. This sheet has both partners describe what role they want and what role they think would help the children, then compare notes and agree on a starting point. Expect to revisit it as the family settles in.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the role I want to play with the children"}, {"id": "f1", "type": "textarea", "label": "Partner A: where I want to defer to my partner"}, {"id": "f2", "type": "textarea", "label": "Partner B: the role I want to play with the children"}, {"id": "f3", "type": "textarea", "label": "Partner B: where I want to defer to my partner"}, {"id": "f4", "type": "textarea", "label": "One agreement we are making for now"}]'::jsonb, array['couples', 'parenting', 'family']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('long-distance-connection-plan', 'Long-Distance Connection Plan', 'couples'::resource_kind, 'Has a couple build a concrete plan for staying connected across distance and time zones.', 'Give a long-distance couple a shared, concrete plan instead of leaving connection to chance.', array['Couples']::text[], '20 minutes', 'Distance strips out the small, ordinary contact that keeps most couples connected, so this plan has both partners name what kind of contact they actually want, calls, messages, shared shows or games, and agree on a rough rhythm that fits both schedules and time zones. Revisit the plan when either partner''s routine changes. The goal is a plan both partners chose, not one imposed by whoever misses the other more.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the kind of contact I want most"}, {"id": "f1", "type": "textarea", "label": "Partner A: what has been hardest about the distance"}, {"id": "f2", "type": "textarea", "label": "Partner B: the kind of contact I want most"}, {"id": "f3", "type": "textarea", "label": "Partner B: what has been hardest about the distance"}, {"id": "f4", "type": "textarea", "label": "A rhythm of contact we are agreeing to try"}]'::jsonb, array['couples', 'connection', 'communication']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('money-values-comparison-sheet', 'Money Values Comparison Sheet', 'couples'::resource_kind, 'Has both partners name what money means to them before working out shared spending decisions.', 'Help a couple talk about the values behind money before the numbers themselves.', array['Couples']::text[], '20 minutes', 'Money arguments are often really values arguments, one partner spending toward security and the other toward experience, without either naming it that way. This sheet has each partner describe what money represents to them, safety, freedom, generosity, before moving to any specific budget conversation. Understanding the value underneath a spending habit usually makes the practical negotiation that follows much easier.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what money represents to me"}, {"id": "f1", "type": "textarea", "label": "Partner A: a spending habit that reflects that value"}, {"id": "f2", "type": "textarea", "label": "Partner B: what money represents to me"}, {"id": "f3", "type": "textarea", "label": "Partner B: a spending habit that reflects that value"}, {"id": "f4", "type": "textarea", "label": "Where our values overlap or differ"}]'::jsonb, array['couples', 'money', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('career-transition-team-planning-sheet', 'Career Transition Team Planning Sheet', 'couples'::resource_kind, 'Has a couple plan together how a job change, move or return to school will be shared between them.', 'Give a couple a shared plan for absorbing the load of one partner''s career transition.', array['Couples']::text[], '20 minutes', 'A career change, whether a new job, a return to school or a move, usually reshapes both partners'' daily lives, not just the one making the change, and unspoken expectations about who picks up the slack can cause resentment. This sheet has both partners name what will shift, who will carry which tasks during the transition, and when to check back in. Treat the plan as a draft to be adjusted once the transition is underway.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how this transition affects my daily life"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I am willing to take on during it"}, {"id": "f2", "type": "textarea", "label": "Partner B: how this transition affects my daily life"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I am willing to take on during it"}, {"id": "f4", "type": "textarea", "label": "When we will check back in on how it is going"}]'::jsonb, array['couples', 'life transitions', 'support']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('friendship-circle-balance-check', 'Friendship Circle Balance Check', 'couples'::resource_kind, 'Has both partners map their outside friendships to see if either feels isolated from support outside the relationship.', 'Help a couple notice whether one or both partners have let outside friendships lapse.', array['Couples']::text[], '20 minutes', 'A relationship that becomes each partner''s only source of support can end up carrying more weight than it can hold, so this check has both partners map who else they lean on and how often. Compare notes on whether either partner''s circle has thinned out since the relationship began, and talk about what would help rebuild it without either partner feeling threatened by the other''s outside friendships.', '[{"id": "f0", "type": "textarea", "label": "Partner A: who I lean on outside this relationship"}, {"id": "f1", "type": "textarea", "label": "Partner A: how that circle has changed over time"}, {"id": "f2", "type": "textarea", "label": "Partner B: who I lean on outside this relationship"}, {"id": "f3", "type": "textarea", "label": "Partner B: how that circle has changed over time"}, {"id": "f4", "type": "textarea", "label": "One step either of us could take to reconnect with a friend"}]'::jsonb, array['couples', 'connection', 'support']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('new-sibling-adjustment-book', 'New Sibling Adjustment Book', 'kids'::resource_kind, 'A child makes a small book about becoming a big sibling to process the change.', 'Help a young child put words and pictures to the changes a new sibling brings.', array['Children']::text[], '20 minutes', 'A new baby reshapes a young child''s world, attention especially, and this has the parent and child make a simple book together with a page for feelings about the baby, a page for what stays the same, and a page for a special job only the older sibling gets to do. Let the child dictate or draw rather than correcting their answers. Revisit the book in the weeks after the baby arrives.', '[{"id": "f0", "type": "textarea", "label": "A page about how I feel about the new baby"}, {"id": "f1", "type": "textarea", "label": "A page about something that stays the same for me"}, {"id": "f2", "type": "textarea", "label": "A page about my special big-sibling job"}, {"id": "f3", "type": "textarea", "label": "A page about something I am excited about"}, {"id": "f4", "type": "textarea", "label": "A page about something that feels hard right now"}]'::jsonb, array['children', 'family', 'art']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('first-day-jitters-plan', 'First Day Jitters Plan', 'kids'::resource_kind, 'A child and parent build a simple plan for a nervous first day at a new school or activity.', 'Give a nervous child a concrete plan to hold onto before a first day.', array['Children']::text[], '20 minutes', 'A first day at a new school, camp or activity can bring up big nerves that are hard for a young child to put into words, and having a concrete plan in hand tends to help more than reassurance alone. The parent and child draw out what the morning will look like step by step, and agree on one small comfort item or phrase the child can use if they feel scared. Practice the plan out loud together before the day arrives.', '[{"id": "f0", "type": "textarea", "label": "What I am nervous about"}, {"id": "f1", "type": "textarea", "label": "What the morning will look like, step by step"}, {"id": "f2", "type": "textarea", "label": "My comfort item or phrase for if I feel scared"}, {"id": "f3", "type": "textarea", "label": "Who I can look for if I need help"}, {"id": "f4", "type": "textarea", "label": "One thing I am a little excited about"}]'::jsonb, array['children', 'anxiety', 'parenting']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('screen-time-family-agreement-craft', 'Screen Time Family Agreement Craft', 'kids'::resource_kind, 'A child decorates a household screen time agreement they helped write.', 'Give a family a screen time agreement the child had a hand in creating.', array['Children']::text[], '20 minutes', 'A screen time rule the child helped write tends to stick better than one simply handed down, so the parent and child talk through when screens are and are not used, then the child decorates a poster listing the agreement to hang somewhere visible. Keep the child''s input genuine on at least a few points, even if the parent sets the outer limits. Revisit the poster if it stops matching what actually happens.', '[{"id": "f0", "type": "textarea", "label": "Times screens are okay in our house"}, {"id": "f1", "type": "textarea", "label": "Times screens are not okay in our house"}, {"id": "f2", "type": "textarea", "label": "What I want to do instead during no-screen times"}, {"id": "f3", "type": "textarea", "label": "What happens if the agreement is not followed"}, {"id": "f4", "type": "textarea", "label": "How I decorated my poster"}]'::jsonb, array['children', 'habits', 'family']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('growth-mindset-poster-craft', 'Growth Mindset Poster Craft', 'kids'::resource_kind, 'A child illustrates the difference between not being able to do something yet and never.', 'Help a child build language for approaching a hard task as a skill still in progress.', array['Children']::text[], '20 minutes', 'Young children often treat a hard task as proof they simply cannot do it, and this craft gives them a concrete way to add the word yet to that sentence instead. The child draws or writes something they find hard now next to a picture of what it might look like once they have practiced it more. Keep the poster somewhere visible and refer back to it the next time a task feels too hard.', '[{"id": "f0", "type": "textarea", "label": "Something that feels hard for me right now"}, {"id": "f1", "type": "textarea", "label": "What I say to myself when it feels hard"}, {"id": "f2", "type": "textarea", "label": "What I could say instead, adding the word yet"}, {"id": "f3", "type": "textarea", "label": "A time I got better at something with practice"}, {"id": "f4", "type": "textarea", "label": "What I drew for my poster"}]'::jsonb, array['children', 'self-esteem', 'art']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('kindness-tally-chain-craft', 'Kindness Tally Chain Craft', 'kids'::resource_kind, 'A child builds a paper chain of kind acts done or received to make kindness visible over time.', 'Give a child a visible, growing record of kindness given and received.', array['Children']::text[], '20 minutes', 'Kindness can feel abstract to a young child, so this craft has them add a paper link to a growing chain each time they do or notice a kind act, writing or drawing what happened on the link. The chain grows across a week or two and becomes something the child can see and be proud of. Keep the focus on noticing kindness rather than turning it into a reward system.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did today"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me today"}, {"id": "f2", "type": "textarea", "label": "How it felt to add a new link to the chain"}, {"id": "f3", "type": "textarea", "label": "Who I want to be kind to tomorrow"}, {"id": "f4", "type": "textarea", "label": "How long my chain has grown"}]'::jsonb, array['children', 'kindness', 'art']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('gratitude-circle-toss', 'Gratitude Circle Toss', 'game'::resource_kind, 'A group tosses a soft ball, naming something they are grateful for each time they catch it.', 'Give a group a quick, moving way to practice noticing and naming gratitude out loud.', array['Groups', 'Children']::text[], '15 minutes', 'Sitting still and writing a gratitude list can feel like a chore to a group, so this game keeps it moving: players toss a soft ball around a circle, and whoever catches it names one thing they are grateful for before tossing it on. Keep the pace quick and playful, and allow repeats since younger groups often circle back to favorites. Debrief briefly on whether anything surprised the group.', '[{"id": "f0", "type": "textarea", "label": "Something I named when I caught the ball"}, {"id": "f1", "type": "textarea", "label": "Something someone else said that stuck with me"}, {"id": "f2", "type": "textarea", "label": "Whether gratitude got easier or harder to name as we went"}, {"id": "f3", "type": "textarea", "label": "One thing I noticed about the group''s answers"}, {"id": "f4", "type": "textarea", "label": "Something I am grateful for that I did not get to say"}]'::jsonb, array['gratitude', 'group', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('change-and-transition-card-sort-game', 'Change and Transition Card Sort Game', 'game'::resource_kind, 'A group sorts cards describing common reactions to change into which ones feel familiar.', 'Normalize a range of reactions to change by sorting them as a group activity.', array['Groups']::text[], '20 minutes', 'Change brings up a wide range of reactions, relief, grief, excitement and dread often all at once, and this game has a group sort cards printed with different reactions into piles of familiar, unfamiliar and surprising. Debrief on how differently people react to the same kind of change and why that variety makes sense rather than being a sign anyone is reacting wrongly. Keep the tone curious rather than clinical.', '[{"id": "f0", "type": "textarea", "label": "A reaction card that felt very familiar to me"}, {"id": "f1", "type": "textarea", "label": "A reaction card that surprised me"}, {"id": "f2", "type": "textarea", "label": "A change I am currently going through"}, {"id": "f3", "type": "textarea", "label": "Which cards from the sort apply to that change for me"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how differently the group reacted"}]'::jsonb, array['life transitions', 'group', 'psychoeducation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('team-trust-walk-game', 'Team Trust Walk Game', 'game'::resource_kind, 'Pairs take turns guiding a blindfolded partner through a simple obstacle course, then debrief on trust.', 'Give a group a hands-on experience of giving and receiving trust to debrief afterward.', array['Groups']::text[], '20 minutes', 'One partner is blindfolded and guided by the other through a simple, safe obstacle course using only voice instructions, then the pair switches roles. Keep the course genuinely safe and check in before starting that both partners consent to the exercise. The debrief afterward, on what made trusting easy or hard and what made guiding easy or hard, usually carries more weight than the walk itself.', '[{"id": "f0", "type": "textarea", "label": "What it felt like to be guided"}, {"id": "f1", "type": "textarea", "label": "What it felt like to guide someone else"}, {"id": "f2", "type": "textarea", "label": "What made trusting my partner easier or harder"}, {"id": "f3", "type": "textarea", "label": "What made giving clear guidance easier or harder"}, {"id": "f4", "type": "textarea", "label": "How this connects to trust outside the game"}]'::jsonb, array['group', 'connection']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('feelings-detective-board-game', 'Feelings Detective Board Game', 'game'::resource_kind, 'Players move around a simple board naming feeling clues to earn a magnifying glass token.', 'Build a young child''s feeling-word vocabulary through a playful board game format.', array['Children', 'Groups']::text[], '20 minutes', 'Players take turns rolling a die and moving around a simple board, and each landing space shows a feeling clue, a facial expression or a short scenario, that the player names to earn a magnifying glass token. Keep the pace light and celebratory rather than quiz-like, and offer hints freely for younger players. Whoever collects the most tokens by the end wins, though the naming practice is the real point.', '[{"id": "f0", "type": "textarea", "label": "A feeling clue I figured out during the game"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard for me to name"}, {"id": "f2", "type": "textarea", "label": "A time I actually felt one of the feelings from the board"}, {"id": "f3", "type": "textarea", "label": "How many tokens I collected"}, {"id": "f4", "type": "textarea", "label": "A new feeling word I learned"}]'::jsonb, array['emotion identification', 'play', 'children', 'group']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('values-bingo', 'Values Bingo', 'game'::resource_kind, 'A group plays bingo with values instead of numbers to spark conversation about what matters to each player.', 'Use a familiar bingo format to get a group talking about personal values.', array['Groups']::text[], '20 minutes', 'Each player gets a bingo card filled with values instead of numbers, connection, honesty, adventure, and marks a square whenever that value comes up as meaningful to them during a round of quick sharing. The game rewards genuine reflection over speed, so keep rounds unhurried. Debrief on which values came up most for the group and which felt more personal or surprising.', '[{"id": "f0", "type": "textarea", "label": "A value I marked on my card and why"}, {"id": "f1", "type": "textarea", "label": "A value on my card I was surprised to connect with"}, {"id": "f2", "type": "textarea", "label": "A value that did not resonate with me at all"}, {"id": "f3", "type": "textarea", "label": "Whether I got bingo, and on which values"}, {"id": "f4", "type": "textarea", "label": "One value I want to act on more this week"}]'::jsonb, array['values', 'group', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('body-based-safety-cues-checklist', 'Body-Based Safety Cues Checklist', 'worksheet'::resource_kind, 'Lists physical and environmental cues a client can use to confirm the present moment is safe.', 'Give a client a quick physical checklist for confirming safety in the here and now.', array['Adults', 'Teens']::text[], '15 minutes', 'When a trigger pulls attention into the past, a fast physical checklist can help a client confirm what is actually true right now: doors locked, feet on the floor, a name and today''s date recalled out loud. This is meant to be completed in session first so the clinician can see what lands, then carried as a card the client can use on their own. It is a grounding tool, not a place to recount what happened.', '[{"id": "f0", "type": "textarea", "label": "Cues I checked to confirm I am safe right now"}, {"id": "f1", "type": "textarea", "label": "What helped me feel most anchored in the present"}, {"id": "f2", "type": "textarea", "label": "What I will say to myself when I use this card"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this checklist"}, {"id": "f4", "type": "textarea", "label": "Who I can call if grounding alone is not enough"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('present-tense-anchoring-sheet', 'Present-Tense Anchoring Sheet', 'cbt'::resource_kind, 'Practices naming five present-moment facts to interrupt a shift into past-tense activation.', 'Help a client build a quick, repeatable way to return attention to the present moment.', array['Adults', 'Teens']::text[], '15 minutes', 'A trigger can pull attention into a past moment so quickly that a client only notices after they are already activated, so this sheet practices a fast return: naming today''s date, the room, and five things currently visible, out loud or on paper. Practice it in session while calm first so it is familiar before it is needed. This is a grounding skill, not a place to describe what happened.', '[{"id": "f0", "type": "textarea", "label": "Today''s date and where I am right now"}, {"id": "f1", "type": "textarea", "label": "Five things I can see right now"}, {"id": "f2", "type": "textarea", "label": "One thing that tells me this moment is different from then"}, {"id": "f3", "type": "textarea", "label": "How activated I felt before and after, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "When I will practice this on my own this week"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core CBT']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('anchored-in-the-room-practice', 'Anchored in the Room Practice', 'act'::resource_kind, 'Uses defusion language to separate a trauma memory from the present physical room.', 'Help a client notice a memory as a mental event happening now, separate from the room they are actually in.', array['Adults']::text[], '10 minutes', 'A flashback can feel like the past is happening again, and this practice uses simple defusion language, noticing ''I am having the memory that,'' paired with naming the actual room, to help a client hold both facts at once: the memory is present, and so is the room. This is a stabilizing practice for the present moment, not an invitation to describe the memory''s content.', '[{"id": "f0", "type": "textarea", "label": "The phrase I used to notice the memory as a memory"}, {"id": "f1", "type": "textarea", "label": "Three facts about the actual room I am in"}, {"id": "f2", "type": "textarea", "label": "How holding both at once felt"}, {"id": "f3", "type": "textarea", "label": "What helped the most"}, {"id": "f4", "type": "textarea", "label": "When I could use this phrase again this week"}]'::jsonb, array['PTSD and trauma', 'core ACT', 'grounding']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('trauma-activation-tipp-card', 'Trauma Activation TIPP Card', 'dbt'::resource_kind, 'A pocket card of fast body-based skills for calming intense activation in the moment.', 'Give a client a fast physical way to bring down intense activation before it escalates further.', array['Adults', 'Teens']::text[], 'Five minutes', 'When activation spikes fast, changing body temperature, intense exercise, paced breathing or paired muscle relaxation can bring the nervous system down more quickly than talking it through. This card lists each option briefly so a client can reach for whichever is available, a cold splash of water, a short fast walk, slow counted breaths. Practice each option once in session so none of them are unfamiliar when they are actually needed.', '[{"id": "f0", "type": "textarea", "label": "Which skill on the card I used"}, {"id": "f1", "type": "textarea", "label": "My activation level before, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "My activation level after, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Where I was and what was available to me"}, {"id": "f4", "type": "textarea", "label": "Which skill I want to keep close by"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'regulation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('partner-debrief-after-activation-sheet', 'Partner Debrief After Activation Sheet', 'couples'::resource_kind, 'Gives both partners a short, structured way to check in after one partner has a triggered moment.', 'Help a couple debrief after an activation episode without either partner having to relive the details.', array['Couples']::text[], '20 minutes', 'After a triggered moment passes, partners often do not know what to say, either overexplaining or avoiding it entirely, and this sheet offers a short structure instead: what helped, what did not, and what the surviving partner needs going forward. It intentionally does not ask what triggered the moment or what the memory contained. Keep it brief and check in again once both partners feel settled.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helped me during that moment"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need from my partner afterward"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I noticed and did during that moment"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I want to understand better for next time"}, {"id": "f4", "type": "textarea", "label": "One thing we will try differently next time"}]'::jsonb, array['PTSD and trauma', 'couples', 'support']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('worry-postponement-trial-card', 'Worry Postponement Trial Card', 'cbt'::resource_kind, 'Has a client set a daily worry appointment and defer intrusive worry to it during the day.', 'Teach a client to defer worry to a set time rather than suppress or follow it immediately.', array['Adults', 'Teens']::text[], 'One week', 'Trying to stop a worry outright often backfires, so this card has a client note the worry briefly when it shows up and defer full attention to a fixed fifteen-minute worry appointment later that day. Many worries lose urgency by the time the appointment arrives. Track what happens at the appointment itself, since that is where the real practice happens.', '[{"id": "f0", "type": "textarea", "label": "A worry I noted and deferred today"}, {"id": "f1", "type": "textarea", "label": "What time my worry appointment was"}, {"id": "f2", "type": "textarea", "label": "Whether the worry still felt urgent at that time"}, {"id": "f3", "type": "textarea", "label": "What I did with it during the appointment"}, {"id": "f4", "type": "textarea", "label": "What I noticed across the week"}]'::jsonb, array['anxiety', 'core CBT', 'worry']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('anxious-mind-radio-station-practice', 'Anxious Mind Radio Station Practice', 'act'::resource_kind, 'Uses a radio station metaphor to help a client notice anxious thoughts without tuning in fully.', 'Give a client a defusion tool for noticing anxious thoughts as background noise rather than instructions.', array['Adults', 'Teens']::text[], '10 minutes', 'Anxious thoughts can play on a loop like a radio station a client did not choose to tune into, and this practice has them notice the broadcast without turning up the volume: ''Radio Anxiety is playing that thought again.'' Naming it this way creates a small gap between the client and the thought, enough room to keep acting on what matters even while the station keeps playing.', '[{"id": "f0", "type": "textarea", "label": "The anxious thought playing on the station today"}, {"id": "f1", "type": "textarea", "label": "What I noticed when I named it as a broadcast"}, {"id": "f2", "type": "textarea", "label": "What I did instead of turning up the volume"}, {"id": "f3", "type": "textarea", "label": "How much room that gap created, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What I want to keep doing even while the station plays"}]'::jsonb, array['anxiety', 'core ACT', 'defusion']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('worry-cloud-watching-craft', 'Worry Cloud Watching Craft', 'kids'::resource_kind, 'A child draws their worry as changing weather to show that feelings pass and shift.', 'Give a child a concrete image for understanding that anxious feelings change and pass.', array['Children']::text[], '20 minutes', 'Young children often experience worry as permanent, so this craft has them draw their worry as a weather report, stormy, cloudy, sunny, and make a few panels showing how it has changed across a day or week. Talk with the parent about noticing and naming the weather together at home. The goal is showing the child that feelings move, not fixing the weather itself.', '[{"id": "f0", "type": "textarea", "label": "My worry weather today"}, {"id": "f1", "type": "textarea", "label": "What made the weather change during the day"}, {"id": "f2", "type": "textarea", "label": "A time my worry weather turned sunnier"}, {"id": "f3", "type": "textarea", "label": "Who I can tell when my weather feels stormy"}, {"id": "f4", "type": "textarea", "label": "What I drew for today''s forecast"}]'::jsonb, array['anxiety', 'children', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('worry-or-fact-sorting-relay', 'Worry or Fact Sorting Relay', 'game'::resource_kind, 'Teams race to sort statement cards into worries and facts before a group debrief.', 'Use a fast-paced sorting relay to practice telling a worry apart from a verified fact.', array['Groups', 'Teens']::text[], '20 minutes', 'Two teams race to sort a stack of cards, some worries and some verified facts, into the correct pile before time runs out, then the group reviews the sort together and discusses any cards that were tricky. Keep the pace lively and the cards realistic to the group''s own worries where possible. The debrief matters more than who wins the relay.', '[{"id": "f0", "type": "textarea", "label": "A card I sorted quickly"}, {"id": "f1", "type": "textarea", "label": "A card that was tricky to sort"}, {"id": "f2", "type": "textarea", "label": "What made the difference between a worry and a fact"}, {"id": "f3", "type": "textarea", "label": "A worry of my own I could sort this way"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how the group did"}]'::jsonb, array['anxiety', 'group', 'thinking traps']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('anxiety-vulnerability-factors-check', 'Anxiety Vulnerability Factors Check', 'dbt'::resource_kind, 'Tracks sleep, food, substance use and physical strain to spot what raises anxiety''s baseline.', 'Help a client notice the physical factors that make anxiety easier or harder to manage on a given day.', array['Adults', 'Teens']::text[], '10 minutes', 'Anxiety is easier to ride out on some days than others, often because of factors that have nothing to do with the worry itself: poor sleep, skipped meals, illness or physical strain. This check has a client rate a few of these factors each day alongside their anxiety level, so patterns become visible over time. It is meant to inform planning, not to explain away the anxiety entirely.', '[{"id": "f0", "type": "textarea", "label": "My sleep last night, rated 0 to 10"}, {"id": "f1", "type": "textarea", "label": "Whether I ate regularly today"}, {"id": "f2", "type": "textarea", "label": "Any physical strain or illness today"}, {"id": "f3", "type": "textarea", "label": "My anxiety level today, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What I notice connecting the two"}]'::jsonb, array['anxiety', 'distress tolerance', 'self-monitoring']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('getting-up-micro-steps-plan', 'Getting-Up Micro-Steps Plan', 'cbt'::resource_kind, 'Breaks the first hour of the day into the smallest possible steps for a client stuck in low mood.', 'Give a client a low-bar plan for starting the day when everything feels heavy.', array['Adults']::text[], 'One week', 'When mood is very low, even a normal morning routine can feel impossible, so this plan breaks the first hour into steps small enough to actually complete: feet on the floor, one glass of water, opening the curtains. Momentum matters more than speed here. Track only whether each micro-step happened, not how the client felt about doing it.', '[{"id": "f0", "type": "textarea", "label": "My micro-step plan for the first hour"}, {"id": "f1", "type": "textarea", "label": "Which steps I completed today"}, {"id": "f2", "type": "textarea", "label": "What got in the way of any I skipped"}, {"id": "f3", "type": "textarea", "label": "How I felt once I had done even one step"}, {"id": "f4", "type": "textarea", "label": "What I want to add or drop from the plan"}]'::jsonb, array['depression', 'core CBT', 'behavioral activation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('low-mood-values-anchor-card', 'Low Mood Values Anchor Card', 'act'::resource_kind, 'A pocket card naming one value a client can act on in a small way even on a low day.', 'Give a client a small, values-based action to reach for on days when motivation is absent.', array['Adults']::text[], '10 minutes', 'Waiting for motivation before acting on what matters often means waiting indefinitely when mood is low, so this card has a client identify one value, connection, care, creativity, and one tiny action that expresses it regardless of mood. The action should be small enough to be doable even on a hard day. Keep it visible somewhere the client will actually see it.', '[{"id": "f0", "type": "textarea", "label": "A value I want to act on even on a low day"}, {"id": "f1", "type": "textarea", "label": "One tiny action that expresses it"}, {"id": "f2", "type": "textarea", "label": "A day I used the card"}, {"id": "f3", "type": "textarea", "label": "What happened when I acted despite low mood"}, {"id": "f4", "type": "textarea", "label": "What I want to keep on the card going forward"}]'::jsonb, array['depression', 'core ACT', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('energy-budget-for-low-mood-days-sheet', 'Energy Budget for Low Mood Days Sheet', 'worksheet'::resource_kind, 'Helps a client allocate limited energy across a day''s demands rather than pushing through all of them.', 'Help a client triage a low-energy day instead of trying to meet every demand at full capacity.', array['Adults']::text[], '15 minutes', 'On a low-mood day, trying to meet every ordinary demand at full capacity usually backfires and deepens the exhaustion, so this sheet has a client list the day''s demands and sort them into must-do, could-shrink and can-skip. Revisiting the sheet at the end of the day, comparing plan to what actually happened, without judgment, tends to be the most useful part.', '[{"id": "f0", "type": "textarea", "label": "Today''s demands, listed out"}, {"id": "f1", "type": "textarea", "label": "Which ones truly must happen today"}, {"id": "f2", "type": "textarea", "label": "Which ones I could shrink to a smaller version"}, {"id": "f3", "type": "textarea", "label": "Which ones I can skip entirely today"}, {"id": "f4", "type": "textarea", "label": "How the day actually went compared with the plan"}]'::jsonb, array['depression', 'self-monitoring', 'behavioral activation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('partner-check-in-without-fixing-script', 'Partner Check-In Without Fixing Script', 'couples'::resource_kind, 'Gives the supporting partner a script for checking in on low mood without jumping to solutions.', 'Help a supporting partner offer presence during a low-mood stretch instead of unsolicited fixes.', array['Couples']::text[], '15 minutes', 'A partner watching someone move through a low-mood stretch often reaches for solutions out of care, which can land as pressure rather than support. This script gives the supporting partner a few open questions to ask instead, what would help right now, do you want company or space, and a reminder to wait for an answer before offering a fix. Both partners can revise the script together.', '[{"id": "f0", "type": "textarea", "label": "Supporting partner: a question I will ask instead of offering a fix"}, {"id": "f1", "type": "textarea", "label": "Partner with low mood: what actually helps me most right now"}, {"id": "f2", "type": "textarea", "label": "Partner with low mood: what does not help, even if well meant"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what I need in order to keep showing up"}, {"id": "f4", "type": "textarea", "label": "One agreement we are making about check-ins"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('small-joys-sticker-map', 'Small Joys Sticker Map', 'kids'::resource_kind, 'A child adds a sticker to a map each time they notice a small good moment during a low stretch.', 'Help a child notice small good moments during a stretch of low mood or sadness.', array['Children']::text[], '20 minutes', 'A child moving through a stretch of sadness or low energy can lose track of small good moments entirely, so this map has them add a sticker to a simple drawn map each time they notice one, a favorite snack, a funny moment, a hug. The parent helps by pointing out moments the child might miss on their own. Look at the growing map together at the end of the week.', '[{"id": "f0", "type": "textarea", "label": "A small good moment I noticed today"}, {"id": "f1", "type": "textarea", "label": "Where I put my sticker on the map"}, {"id": "f2", "type": "textarea", "label": "A moment my parent helped me notice"}, {"id": "f3", "type": "textarea", "label": "How many stickers I have so far"}, {"id": "f4", "type": "textarea", "label": "What I want to notice more of this week"}]'::jsonb, array['depression', 'children', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('transition-warning-countdown-log', 'Transition Warning Countdown Log', 'cbt'::resource_kind, 'Tracks how advance warnings before switching tasks affect how smoothly the switch goes.', 'Help a client test whether advance warnings make task transitions easier to manage.', array['Adults', 'Teens']::text[], 'One week', 'Switching between tasks can be one of the hardest parts of a day, and this log has a client try giving themselves a short warning, five or ten minutes, before a planned switch, then rate how the transition went compared with switches made with no warning. Over a week the pattern usually shows whether the warning genuinely helps or whether other supports are needed instead.', '[{"id": "f0", "type": "textarea", "label": "The transition I was making"}, {"id": "f1", "type": "textarea", "label": "Whether I gave myself a warning beforehand"}, {"id": "f2", "type": "textarea", "label": "How smooth the transition felt, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What made it easier or harder"}, {"id": "f4", "type": "textarea", "label": "What I want to try differently next time"}]'::jsonb, array['ADHD', 'core CBT', 'self-monitoring']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('values-driven-routine-anchor', 'Values-Driven Routine Anchor', 'act'::resource_kind, 'Links one daily routine step to a value so it is easier to return to after it gets skipped.', 'Help a client reconnect a dropped routine to the value it was meant to serve.', array['Adults', 'Teens']::text[], '15 minutes', 'Routines built on willpower alone tend to fall apart quickly, so this practice has a client pick one routine step that keeps slipping and name the value underneath it, health, care for others, creativity, rather than the habit itself. Returning to a value after a skipped day tends to feel more workable than returning to a rule that was already broken. Track attempts rather than streaks.', '[{"id": "f0", "type": "textarea", "label": "The routine step that keeps slipping"}, {"id": "f1", "type": "textarea", "label": "The value underneath it"}, {"id": "f2", "type": "textarea", "label": "A day I skipped it and what happened"}, {"id": "f3", "type": "textarea", "label": "A day I returned to it, even imperfectly"}, {"id": "f4", "type": "textarea", "label": "What returning to the value felt like versus returning to the rule"}]'::jsonb, array['ADHD', 'core ACT', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('emotional-flooding-from-overwhelm-card', 'Emotional Flooding From Overwhelm Card', 'dbt'::resource_kind, 'A short card for when task overwhelm tips into emotional flooding rather than just distraction.', 'Give a client a quick skill for the emotional spike that can follow ADHD-related overwhelm.', array['Adults', 'Teens']::text[], 'Five minutes', 'Task overwhelm can tip quickly into a genuine emotional flood, frustration, shame or panic, that then makes the original task even harder to return to. This card offers a short sequence: name the flood, use one distress tolerance skill to bring intensity down, then decide whether to return to the task or take a real break. The point is separating the emotional spike from the task itself so each can be handled on its own.', '[{"id": "f0", "type": "textarea", "label": "What tipped me into flooding"}, {"id": "f1", "type": "textarea", "label": "The skill I used to bring intensity down"}, {"id": "f2", "type": "textarea", "label": "My intensity before and after, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Whether I returned to the task or took a break"}, {"id": "f4", "type": "textarea", "label": "What I want to remember for next time"}]'::jsonb, array['ADHD', 'distress tolerance', 'regulation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('homework-launch-pad-craft', 'Homework Launch Pad Craft', 'kids'::resource_kind, 'A child decorates a homework starting kit to shrink the gap between deciding to start and actually starting.', 'Give a child a physical kit that reduces the friction of starting homework.', array['Children']::text[], '20 minutes', 'The hardest part of homework for many children with attention challenges is not the work itself but the gap between deciding to start and actually starting, so this craft has the child decorate a small kit, a box or folder, holding everything needed: pencils, a timer, a fidget item. The parent helps set a consistent spot for the kit. Review together whether having it ready actually shortened the delay.', '[{"id": "f0", "type": "textarea", "label": "What I put in my launch pad kit"}, {"id": "f1", "type": "textarea", "label": "Where I decided to keep it"}, {"id": "f2", "type": "textarea", "label": "How long it took me to start homework with the kit ready"}, {"id": "f3", "type": "textarea", "label": "What still made starting hard"}, {"id": "f4", "type": "textarea", "label": "One thing I want to add to the kit"}]'::jsonb, array['ADHD', 'children', 'task initiation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('focus-relay-race-game', 'Focus Relay Race Game', 'game'::resource_kind, 'Teams complete short focused tasks in relay format with brief, planned breaks built in.', 'Practice short bursts of focus with built-in breaks through a playful relay format.', array['Groups', 'Children']::text[], '20 minutes', 'Teams take turns completing a short focused task, a puzzle piece, a simple sequence, then tag a teammate and take a planned short break before their next turn. The structure mirrors a real strategy, working in short bursts with built-in recovery, in a format that feels like play rather than a lesson. Debrief on which parts of the relay felt easiest and hardest to stay focused through.', '[{"id": "f0", "type": "textarea", "label": "The task I completed during my turn"}, {"id": "f1", "type": "textarea", "label": "How focused I felt during my burst"}, {"id": "f2", "type": "textarea", "label": "What the break in between felt like"}, {"id": "f3", "type": "textarea", "label": "Which part of the relay was hardest to focus through"}, {"id": "f4", "type": "textarea", "label": "How this connects to focusing on schoolwork or chores"}]'::jsonb, array['ADHD', 'group', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('substance-use-trigger-chain-sheet', 'Substance Use Trigger Chain Sheet', 'cbt'::resource_kind, 'Maps the chain of events from trigger to substance use to spot an earlier point to intervene.', 'Help a client see the chain of events leading up to substance use, not just the moment itself.', array['Adults']::text[], '15 minutes', 'Substance use rarely happens in a single moment; it usually follows a chain, a trigger, a thought, a feeling, a decision point, that can be mapped after the fact to find an earlier place to intervene next time. This sheet has a client walk backward from a recent instance of use, naming each link, and circle the earliest point where a different choice felt possible. The goal is a map for next time, not a confession.', '[{"id": "f0", "type": "textarea", "label": "The trigger that started the chain"}, {"id": "f1", "type": "textarea", "label": "The thought that followed"}, {"id": "f2", "type": "textarea", "label": "The feeling that followed"}, {"id": "f3", "type": "textarea", "label": "The earliest link where a different choice felt possible"}, {"id": "f4", "type": "textarea", "label": "What that different choice could look like next time"}]'::jsonb, array['addiction', 'core CBT', 'urges']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('values-beyond-the-urge-practice', 'Values Beyond the Urge Practice', 'act'::resource_kind, 'Has a client name a value the urge is temporarily crowding out to widen the choice in the moment.', 'Help a client notice what an urge is crowding out and reconnect with it in the moment.', array['Adults']::text[], '10 minutes', 'An urge can narrow a client''s attention until nothing else seems to matter, so this practice has them name, right in that narrowed moment, one value the urge is currently crowding out, being present for a child, staying employed, self-respect. Naming it does not make the urge disappear, but it widens the field of choice for a moment. Pair this with a concrete coping skill rather than using it alone.', '[{"id": "f0", "type": "textarea", "label": "The urge I am noticing right now, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "The value it is currently crowding out"}, {"id": "f2", "type": "textarea", "label": "What acting on that value would look like right now instead"}, {"id": "f3", "type": "textarea", "label": "What I actually did"}, {"id": "f4", "type": "textarea", "label": "How the urge changed afterward, if at all"}]'::jsonb, array['addiction', 'core ACT', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('urge-riding-practice-card', 'Urge Riding Practice Card', 'dbt'::resource_kind, 'Practices noticing an urge rise, peak and fall without acting on it, timed on a simple card.', 'Help a client build direct experience that an urge passes on its own within minutes.', array['Adults', 'Teens']::text[], '10 minutes', 'An urge often feels like it will only grow unless acted on, but urges typically rise, peak and fall within a fairly short window when nothing is done to feed them. This card has a client time an urge from the moment it is noticed, rating its intensity every few minutes, to build direct evidence that it does pass. If thoughts of self-harm accompany the urge, complete this in session, and 988 can be called or texted anytime between sessions.', '[{"id": "f0", "type": "textarea", "label": "The urge I am timing"}, {"id": "f1", "type": "textarea", "label": "Intensity at the start, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Intensity a few minutes in"}, {"id": "f3", "type": "textarea", "label": "Intensity once it had passed or eased"}, {"id": "f4", "type": "textarea", "label": "What I noticed about riding it out instead of acting"}]'::jsonb, array['addiction', 'distress tolerance', 'urges']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('using-alone-risk-reduction-sheet', 'Using Alone Risk Reduction Sheet', 'worksheet'::resource_kind, 'Helps a client build a safety plan for reducing risk on occasions when substance use happens alone.', 'Give a client a concrete plan for reducing physical risk during a lapse rather than only aiming for none.', array['Adults']::text[], '15 minutes', 'Aiming for zero use can leave no plan at all for the times use actually happens, and unplanned solo use carries more physical risk than use with another person present or aware. This sheet has a client build a concrete plan: someone to check in with, never using entirely alone, keeping naloxone accessible if relevant, and a reminder that 988 can be called or texted in a crisis. This is a safety plan, not a green light.', '[{"id": "f0", "type": "textarea", "label": "Someone I can tell before I use, or check in with after"}, {"id": "f1", "type": "textarea", "label": "What I will keep on hand in case of an emergency"}, {"id": "f2", "type": "textarea", "label": "A place I will avoid using alone"}, {"id": "f3", "type": "textarea", "label": "My plan if things start to feel unsafe"}, {"id": "f4", "type": "textarea", "label": "Who else knows this plan"}]'::jsonb, array['addiction', 'safety planning', 'crisis']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('recovery-trivia-relay-game', 'Recovery Trivia Relay Game', 'game'::resource_kind, 'Teams answer prompt cards about coping, triggers and support to spark group discussion.', 'Use a light trivia format to open group discussion on coping strategies and support.', array['Groups']::text[], '20 minutes', 'Teams take turns drawing a prompt card, naming a coping skill, a common trigger, a support person to call, and earn a point for a genuine answer rather than a technically correct one. The format keeps a heavy topic approachable and gets quieter group members talking. Spend more time on the discussion each card sparks than on keeping score.', '[{"id": "f0", "type": "textarea", "label": "A prompt card I answered"}, {"id": "f1", "type": "textarea", "label": "A coping skill another player named that I want to try"}, {"id": "f2", "type": "textarea", "label": "A trigger someone mentioned that I also recognize"}, {"id": "f3", "type": "textarea", "label": "A support person I could add to my own list"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the group''s answers"}]'::jsonb, array['addiction', 'group', 'coping skills']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('anger-outburst-ledger', 'Anger Outburst Ledger', 'cbt'::resource_kind, 'Tallies what an anger outburst costs against what it seemed to accomplish in the moment.', 'Help a client weigh the real cost of an anger outburst against its momentary payoff.', array['Adults', 'Teens']::text[], '15 minutes', 'In the moment, an angry outburst can feel like it accomplishes something, being heard, feeling powerful, ending an argument, but the actual costs often outweigh that payoff once the dust settles. This ledger has a client list both sides after a recent outburst: what it seemed to get them and what it actually cost in relationships, energy or trust. Comparing the columns side by side is usually more persuasive than being told to calm down.', '[{"id": "f0", "type": "textarea", "label": "The outburst I am reviewing"}, {"id": "f1", "type": "textarea", "label": "What it seemed to get me in the moment"}, {"id": "f2", "type": "textarea", "label": "What it actually cost afterward"}, {"id": "f3", "type": "textarea", "label": "What I could try instead next time"}, {"id": "f4", "type": "textarea", "label": "What I notice comparing the two columns"}]'::jsonb, array['anger management', 'core CBT', 'thinking traps']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('repair-attempt-recognition-sheet', 'Repair Attempt Recognition Sheet', 'couples'::resource_kind, 'Has both partners identify what a genuine repair attempt looks like from the other during an argument.', 'Help a couple recognize and accept each other''s attempts to de-escalate a heated moment.', array['Couples']::text[], '20 minutes', 'Partners often make small repair attempts mid-argument, a joke, a softer tone, reaching for a hand, that go unnoticed or get rejected when tempers are already high. This sheet has each partner describe what their own repair attempts typically look like and what helps them notice and accept their partner''s. Practicing recognition when calm makes it more likely to be caught in the heat of an actual argument.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what my repair attempts usually look like"}, {"id": "f1", "type": "textarea", "label": "Partner A: what helps me notice my partner''s repair attempts"}, {"id": "f2", "type": "textarea", "label": "Partner B: what my repair attempts usually look like"}, {"id": "f3", "type": "textarea", "label": "Partner B: what helps me notice my partner''s repair attempts"}, {"id": "f4", "type": "textarea", "label": "One repair signal we are agreeing to watch for"}]'::jsonb, array['anger management', 'couples', 'repair']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('anger-traffic-light-craft', 'Anger Traffic Light Craft', 'kids'::resource_kind, 'A child builds a traffic light showing calm, warming up and full anger to signal when to use a skill.', 'Give a child a visual signal system for noticing anger building before it peaks.', array['Children']::text[], '20 minutes', 'A traffic light gives a young child a familiar image for the buildup of anger: green for calm, yellow for warming up, red for full anger, and this craft has them decorate one and decide on a skill to try at yellow, before red is reached. The parent''s job is to gently point out the yellow light when they see it, rather than waiting until red. Practice choosing a yellow-light skill together while calm.', '[{"id": "f0", "type": "textarea", "label": "What green, calm, feels like in my body"}, {"id": "f1", "type": "textarea", "label": "What yellow, warming up, feels like in my body"}, {"id": "f2", "type": "textarea", "label": "What red, full anger, feels like in my body"}, {"id": "f3", "type": "textarea", "label": "A skill I will try at yellow"}, {"id": "f4", "type": "textarea", "label": "How my parent can help me notice yellow"}]'::jsonb, array['anger management', 'children', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('cool-down-or-heat-up-sorting-game', 'Cool Down or Heat Up Sorting Game', 'game'::resource_kind, 'A group sorts common reactions into ones that cool an argument down and ones that heat it up.', 'Help a group tell apart de-escalating and escalating responses through a sorting activity.', array['Groups', 'Teens']::text[], '20 minutes', 'Players sort a stack of cards describing common reactions to conflict, raising your voice, taking a breath, name-calling, stepping away, into two piles: cools it down or heats it up. Debrief on any cards the group disagreed about, since context often changes which pile a reaction belongs in. Close by having each player name one cool-down response they want to practice using.', '[{"id": "f0", "type": "textarea", "label": "A card I sorted into cools it down"}, {"id": "f1", "type": "textarea", "label": "A card I sorted into heats it up"}, {"id": "f2", "type": "textarea", "label": "A card the group disagreed about and why"}, {"id": "f3", "type": "textarea", "label": "A cool-down response I want to practice"}, {"id": "f4", "type": "textarea", "label": "A heat-up response I want to catch myself using less"}]'::jsonb, array['anger management', 'group', 'de-escalation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('anger-trigger-pattern-map', 'Anger Trigger Pattern Map', 'worksheet'::resource_kind, 'Maps recurring anger triggers across a week to spot a common thread underneath the specific incidents.', 'Help a client find the pattern underneath a week of separate-seeming angry moments.', array['Adults', 'Teens']::text[], '20 minutes', 'A week of angry moments can look unrelated on the surface, a comment at work, traffic, a sibling''s remark, until they are mapped side by side and a common thread appears, often something like feeling disrespected or feeling rushed. This sheet has a client log each moment briefly across a week, then look for the thread that connects them. Naming the thread often makes the trigger easier to anticipate.', '[{"id": "f0", "type": "textarea", "label": "An angry moment from this week"}, {"id": "f1", "type": "textarea", "label": "What was said or happened right before"}, {"id": "f2", "type": "textarea", "label": "What it seemed to be really about underneath"}, {"id": "f3", "type": "textarea", "label": "Another moment that shares that same thread"}, {"id": "f4", "type": "textarea", "label": "The thread I noticed across the week"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('certainty-seeking-cost-log', 'Certainty Seeking Cost Log', 'cbt'::resource_kind, 'Tracks how much time reassurance seeking or checking actually costs across a week.', 'Help a client see the real time cost of certainty-seeking behaviors across a week.', array['Adults', 'Teens']::text[], 'One week', 'Checking and reassurance seeking can feel like they cost only a moment each time, but added up across a day or week the total is often far larger than a client expects. This log has them tally minutes spent on checking or seeking certainty each day, then review the weekly total together in session. The number itself, rather than any lecture about it, tends to be the more persuasive part.', '[{"id": "f0", "type": "textarea", "label": "A checking or reassurance-seeking moment today"}, {"id": "f1", "type": "textarea", "label": "Roughly how many minutes it took"}, {"id": "f2", "type": "textarea", "label": "What I was trying to feel certain about"}, {"id": "f3", "type": "textarea", "label": "My running total for the day"}, {"id": "f4", "type": "textarea", "label": "What I notice about the week''s total"}]'::jsonb, array['OCD', 'core CBT', 'monitoring']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('thoughts-are-not-threats-practice', 'Thoughts Are Not Threats Practice', 'act'::resource_kind, 'Practices letting an intrusive thought be present without acting to neutralize it.', 'Help a client build tolerance for an intrusive thought''s presence without a ritual to neutralize it.', array['Adults', 'Teens']::text[], '10 minutes', 'An intrusive thought often triggers an urge to do something, a ritual, a mental review, to make the discomfort go away, and this practice has a client instead let the thought sit for a set period without acting on that urge, noting its intensity as it naturally shifts. Start with a short window and build gradually. This is uncomfortable by design; go at a pace the client actually agrees to.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought I practiced sitting with"}, {"id": "f1", "type": "textarea", "label": "How long I let it sit without acting on the urge"}, {"id": "f2", "type": "textarea", "label": "Intensity at the start, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Intensity by the end of the window"}, {"id": "f4", "type": "textarea", "label": "What I noticed about not acting on the urge"}]'::jsonb, array['OCD', 'core ACT', 'acceptance']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('uncertainty-tolerance-ladder-for-rituals', 'Uncertainty Tolerance Ladder for Rituals', 'dbt'::resource_kind, 'Builds a graded ladder of ritual-delay steps paired with a distress tolerance skill at each rung.', 'Give a client a graded plan for delaying a ritual, paired with a skill to manage the wait.', array['Adults', 'Teens']::text[], '20 minutes', 'Delaying a ritual outright can feel like too large a jump, so this ladder breaks the delay into graded rungs, thirty seconds, then a minute, then five, each paired with a distress tolerance skill to use during the wait. Move up a rung only once the current one feels manageable. Track intensity at each rung so progress is visible on paper, not just felt.', '[{"id": "f0", "type": "textarea", "label": "The ritual I am building a delay ladder for"}, {"id": "f1", "type": "textarea", "label": "The rung I am currently working on"}, {"id": "f2", "type": "textarea", "label": "The skill I am pairing with the wait"}, {"id": "f3", "type": "textarea", "label": "Intensity during the wait, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "Whether I am ready to move up a rung"}]'::jsonb, array['OCD', 'distress tolerance', 'urges']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('bossy-thought-puppet-show', 'Bossy Thought Puppet Show', 'kids'::resource_kind, 'A child makes a puppet for their bossy, worried thought and practices talking back to it.', 'Give a child a playful, externalized way to talk back to an intrusive worry thought.', array['Children']::text[], '20 minutes', 'Giving the intrusive thought a name and a puppet face turns an invisible, confusing experience into something a child can see and respond to, and this activity has the child and parent build a simple puppet, then practice a few talk-back lines together, like ''You don''t get to boss me today.'' Keep the tone playful rather than combative. Practice the lines when calm before trying them in the moment.', '[{"id": "f0", "type": "textarea", "label": "What I named my bossy thought puppet"}, {"id": "f1", "type": "textarea", "label": "A talk-back line I practiced"}, {"id": "f2", "type": "textarea", "label": "A time the bossy thought showed up today"}, {"id": "f3", "type": "textarea", "label": "What I said back to it"}, {"id": "f4", "type": "textarea", "label": "How it felt to talk back instead of obeying"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('ritual-function-worksheet', 'Ritual Function Worksheet', 'worksheet'::resource_kind, 'Maps what a ritual is meant to prevent against how often that outcome actually occurs without it.', 'Help a client see the gap between what a ritual is meant to prevent and how often that outcome happens.', array['Adults', 'Teens']::text[], '20 minutes', 'Every ritual is trying to prevent something, even if the client cannot always name it clearly, so this sheet has them write out what the ritual is meant to prevent and then track, over the days that follow, how often that feared outcome actually occurs on days the ritual is skipped or delayed. The gap between the fear and the actual outcome frequency is often the most useful finding on the page.', '[{"id": "f0", "type": "textarea", "label": "The ritual I am mapping"}, {"id": "f1", "type": "textarea", "label": "What I believe it is meant to prevent"}, {"id": "f2", "type": "textarea", "label": "A day I delayed or skipped it"}, {"id": "f3", "type": "textarea", "label": "What actually happened that day"}, {"id": "f4", "type": "textarea", "label": "What I notice comparing the fear to the outcome"}]'::jsonb, array['OCD', 'self-monitoring', 'formulation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('sensation-timeline-cross-check', 'Sensation Timeline Cross-Check', 'cbt'::resource_kind, 'Compares how long a client predicted a panic sensation would last against how long it actually did.', 'Give a client direct evidence that panic sensations pass more quickly than predicted.', array['Adults', 'Teens']::text[], '15 minutes', 'In the middle of a panic surge, sensations can feel like they will last indefinitely, so this sheet has a client note their prediction for how long a sensation will last at the start, then log the actual duration once it passes. Comparing predicted to actual duration across several episodes tends to shift the felt sense of danger more than being told the sensation is harmless.', '[{"id": "f0", "type": "textarea", "label": "The sensation I am tracking"}, {"id": "f1", "type": "textarea", "label": "My prediction for how long it would last"}, {"id": "f2", "type": "textarea", "label": "How long it actually lasted"}, {"id": "f3", "type": "textarea", "label": "What I did while it was happening"}, {"id": "f4", "type": "textarea", "label": "What I notice comparing prediction to actual"}]'::jsonb, array['panic attacks', 'core CBT', 'prediction']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('making-room-for-the-surge-practice', 'Making Room for the Surge Practice', 'act'::resource_kind, 'Practices making physical space for a panic sensation rather than fighting to push it away.', 'Help a client shift from fighting a panic sensation to making room for it instead.', array['Adults', 'Teens']::text[], '10 minutes', 'Fighting a panic sensation, trying to force it away, often intensifies it, so this practice has a client instead imagine making literal room in their body for the sensation, softening around it rather than bracing against it. This is not the same as liking the sensation or wanting it to stay; it is choosing not to add a second layer of struggle on top of the first.', '[{"id": "f0", "type": "textarea", "label": "The sensation I practiced making room for"}, {"id": "f1", "type": "textarea", "label": "What softening around it, instead of bracing, felt like"}, {"id": "f2", "type": "textarea", "label": "Intensity before making room, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Intensity after making room, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What I noticed about fighting it less"}]'::jsonb, array['panic attacks', 'core ACT', 'acceptance']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('panic-wave-riding-card', 'Panic Wave Riding Card', 'dbt'::resource_kind, 'A pocket card pairing paced breathing with a mental image of riding out a wave during panic.', 'Give a client a fast, portable skill for the peak of a panic surge.', array['Adults', 'Teens']::text[], 'Five minutes', 'At the peak of a panic surge, a client needs something short and immediate, so this card pairs slow paced breathing with the image of a wave: rising, cresting and always eventually receding. Practice the pairing in session while calm so the breathing pattern and the image are already familiar before an actual episode. Keep the card somewhere it can be reached quickly.', '[{"id": "f0", "type": "textarea", "label": "Where I was when I used the card"}, {"id": "f1", "type": "textarea", "label": "My intensity at the peak, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How the breathing and wave image felt together"}, {"id": "f3", "type": "textarea", "label": "My intensity once the wave had passed"}, {"id": "f4", "type": "textarea", "label": "What I want to remember for next time"}]'::jsonb, array['panic attacks', 'distress tolerance', 'regulation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('partner-panic-coaching-cues-sheet', 'Partner Panic Coaching Cues Sheet', 'couples'::resource_kind, 'Has both partners agree on exact words and actions that help during a panic episode, and which do not.', 'Give a supporting partner clear, agreed-on language to use during a panic episode.', array['Couples']::text[], '20 minutes', 'A well-meaning partner can say the wrong thing during a panic episode without knowing it, telling someone to calm down rarely helps, so this sheet has both partners agree in advance on specific phrases and actions that actually help, and a short list of ones to avoid. Practice the agreed phrases together while calm so they come more naturally under pressure.', '[{"id": "f0", "type": "textarea", "label": "Partner with panic: phrases that actually help me"}, {"id": "f1", "type": "textarea", "label": "Partner with panic: phrases or actions that do not help"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what I will say instead"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what I will do with my body, like staying close or giving space"}, {"id": "f4", "type": "textarea", "label": "One cue word we are agreeing on together"}]'::jsonb, array['panic attacks', 'couples', 'support']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('panic-episode-pattern-sheet', 'Panic Episode Pattern Sheet', 'worksheet'::resource_kind, 'Logs the setting, timing and buildup of several panic episodes to look for a shared pattern.', 'Help a client spot a pattern across several panic episodes instead of viewing each as random.', array['Adults']::text[], '20 minutes', 'Panic episodes can feel like they strike at random, but logging the setting, time of day and buildup across several episodes often reveals a shared pattern, a place, a physical state, a type of situation. This sheet has a client fill in these details after each episode passes rather than trying to remember later. Bring the pattern back to session to plan around it together.', '[{"id": "f0", "type": "textarea", "label": "Where I was when it started"}, {"id": "f1", "type": "textarea", "label": "What was happening in the minutes right before"}, {"id": "f2", "type": "textarea", "label": "How it built up, fast or gradual"}, {"id": "f3", "type": "textarea", "label": "How long it lasted"}, {"id": "f4", "type": "textarea", "label": "What I notice comparing this to earlier episodes"}]'::jsonb, array['panic attacks', 'self-monitoring', 'formulation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('first-then-picture-board-craft', 'First-Then Picture Board Craft', 'kids'::resource_kind, 'A child builds a picture board pairing a hard task with a preferred one to make the sequence visible.', 'Give a young child a visual sequence for getting through a hard task toward a preferred one.', array['Children']::text[], '20 minutes', 'A first-then board makes an abstract instruction concrete for a young child by showing exactly what comes first, the hard part, and then, the preferred part, side by side in pictures. The parent and child build the board together and can swap the pictures as tasks change day to day. Keep the then picture something genuinely available, not a big reward, so the board stays usable daily.', '[{"id": "f0", "type": "textarea", "label": "The first task on my board today"}, {"id": "f1", "type": "textarea", "label": "The then activity I am working toward"}, {"id": "f2", "type": "textarea", "label": "How it felt to see both pictures together"}, {"id": "f3", "type": "textarea", "label": "Whether I finished the first task"}, {"id": "f4", "type": "textarea", "label": "What I want on tomorrow''s board"}]'::jsonb, array['parenting', 'children', 'routines']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('feelings-coaching-script-cards', 'Feelings Coaching Script Cards', 'kids'::resource_kind, 'A parent practices a short script for naming a child''s feeling before moving to problem-solving.', 'Give a parent a short, practiced script for naming a child''s feeling before jumping to a fix.', array['Children']::text[], '20 minutes', 'Parents often move straight to solving a child''s problem, which can leave the child feeling unheard even when the fix is a good one, so these cards give the parent a short script to practice: name what the child seems to be feeling, check if that is right, and only then move toward a solution together. Practice the script out loud with the clinician before trying it during an actual upset moment at home.', '[{"id": "f0", "type": "textarea", "label": "The feeling I named for my child"}, {"id": "f1", "type": "textarea", "label": "How my child responded to being named correctly, or not"}, {"id": "f2", "type": "textarea", "label": "What we moved toward once the feeling was acknowledged"}, {"id": "f3", "type": "textarea", "label": "What was hardest about pausing before fixing"}, {"id": "f4", "type": "textarea", "label": "What I want to practice more"}]'::jsonb, array['parenting', 'children', 'emotion coaching']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('parent-reactivity-trigger-log', 'Parent Reactivity Trigger Log', 'cbt'::resource_kind, 'Logs the moments a parent''s own reaction outpaces the situation to find their personal triggers.', 'Help a parent notice their own triggers for overreacting before working on responding differently.', array['Adults']::text[], 'One week', 'A parent''s reaction sometimes outpaces what a child''s behavior actually calls for, often because the moment taps into something from the parent''s own history or current stress rather than the behavior itself. This log has a parent note moments their reaction felt bigger than the situation, and what was happening for them right before. Recognizing a personal trigger is the first step toward a different response next time.', '[{"id": "f0", "type": "textarea", "label": "The moment my reaction felt bigger than the situation called for"}, {"id": "f1", "type": "textarea", "label": "What was going on for me right before it"}, {"id": "f2", "type": "textarea", "label": "What my reaction actually looked like"}, {"id": "f3", "type": "textarea", "label": "What a smaller, more proportional response could have looked like"}, {"id": "f4", "type": "textarea", "label": "A pattern I am noticing across entries"}]'::jsonb, array['parenting', 'core CBT', 'triggers']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('family-meeting-agenda-sheet', 'Family Meeting Agenda Sheet', 'worksheet'::resource_kind, 'Gives a family a simple recurring agenda for airing concerns and celebrating wins together.', 'Give a family a light, repeatable structure for a regular check-in together.', array['Adults', 'Children']::text[], '20 minutes', 'A short recurring family meeting gives everyone, parents and children alike, a predictable place to raise a concern or share something good, rather than letting issues build up until they spill out at a harder moment. This sheet offers a simple agenda: one appreciation, one concern, one plan, kept brief enough for younger children to stay engaged. Rotate who leads the meeting each week.', '[{"id": "f0", "type": "textarea", "label": "Something we are appreciating this week"}, {"id": "f1", "type": "textarea", "label": "A concern someone wants to raise"}, {"id": "f2", "type": "textarea", "label": "A plan we are agreeing on"}, {"id": "f3", "type": "textarea", "label": "Who is leading next week''s meeting"}, {"id": "f4", "type": "textarea", "label": "How this meeting felt compared with last time"}]'::jsonb, array['parenting', 'family', 'communication']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('calm-parent-role-play-game', 'Calm Parent Role-Play Game', 'game'::resource_kind, 'Parents take turns role-playing a common flashpoint and practicing a calm response out loud.', 'Give parents low-stakes practice responding calmly to a common flashpoint before it happens for real.', array['Groups', 'Adults']::text[], '20 minutes', 'Parents take turns acting out a common flashpoint, a meltdown at a store, a bedtime standoff, first playing it as it usually goes, then replaying it with a calmer response practiced out loud in front of the group. The group offers feedback on what felt genuine and workable. Rehearsing the words in advance tends to make them more available in the actual moment.', '[{"id": "f0", "type": "textarea", "label": "The flashpoint I role-played"}, {"id": "f1", "type": "textarea", "label": "How my first, usual response sounded"}, {"id": "f2", "type": "textarea", "label": "How my calmer replay sounded"}, {"id": "f3", "type": "textarea", "label": "Feedback the group gave me"}, {"id": "f4", "type": "textarea", "label": "A line I want to remember for next time"}]'::jsonb, array['parenting', 'group', 'regulation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('new-parent-reality-check-sheet', 'New Parent Reality Check Sheet', 'worksheet'::resource_kind, 'Compares a new parent''s expectations of early parenthood against their actual daily experience.', 'Help a new parent see the gap between expected and actual early parenthood without judgment.', array['Adults']::text[], '15 minutes', 'New parents often arrive carrying an expectation of how early parenthood would feel that does not match the exhausted, uneven reality they are living, and the gap itself can add guilt on top of exhaustion. This sheet has a client write both columns side by side, expectation and reality, and talk through what the gap brings up. Naming the gap out loud tends to lighten it somewhat.', '[{"id": "f0", "type": "textarea", "label": "What I expected early parenthood to feel like"}, {"id": "f1", "type": "textarea", "label": "What it has actually felt like"}, {"id": "f2", "type": "textarea", "label": "What the gap between the two brings up for me"}, {"id": "f3", "type": "textarea", "label": "What I need to hear or have right now"}, {"id": "f4", "type": "textarea", "label": "One expectation I am willing to let go of"}]'::jsonb, array['perinatal and postpartum', 'self-monitoring', 'psychoeducation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('postpartum-intrusive-thought-log', 'Postpartum Intrusive Thought Log', 'cbt'::resource_kind, 'Logs a frightening postpartum intrusive thought alongside the fact that it was never acted on.', 'Help a new parent see the gap between a frightening intrusive thought and any actual intention to act.', array['Adults']::text[], 'One week', 'Frightening intrusive thoughts about the baby are common after birth and are not the same as wanting to act on them, but the shame around having the thought at all can keep a new parent from telling anyone. This log has a client note the thought and, alongside it, the fact that no action followed, building a written record that the thought and the behavior are two separate things. Complete this in session first.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought I am logging"}, {"id": "f1", "type": "textarea", "label": "How distressing it felt, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I actually did, which was nothing harmful"}, {"id": "f3", "type": "textarea", "label": "What helped me get through the moment"}, {"id": "f4", "type": "textarea", "label": "What I want a clinician or partner to know about this"}]'::jsonb, array['perinatal and postpartum', 'core CBT', 'intrusive thoughts']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('good-enough-parent-values-practice', 'Good Enough Parent Values Practice', 'act'::resource_kind, 'Helps a new parent define what good enough actually means to them, apart from an impossible standard.', 'Help a new parent replace an impossible standard with a workable, values-based one.', array['Adults']::text[], '15 minutes', 'New parents often measure themselves against an impossible standard of doing everything right, and this practice has them instead define what good enough parenting means in their own words, rooted in values like presence or warmth rather than flawless execution. Revisit the definition on hard days, since the impossible standard tends to creep back in during exhaustion.', '[{"id": "f0", "type": "textarea", "label": "The impossible standard I have been holding myself to"}, {"id": "f1", "type": "textarea", "label": "What good enough actually looks like to me"}, {"id": "f2", "type": "textarea", "label": "A moment this week that met that standard"}, {"id": "f3", "type": "textarea", "label": "What I want to let go of measuring myself against"}, {"id": "f4", "type": "textarea", "label": "What I want to remember on a hard day"}]'::jsonb, array['perinatal and postpartum', 'core ACT', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('new-parent-intimacy-timeline-sheet', 'New Parent Intimacy Timeline Sheet', 'couples'::resource_kind, 'Has both partners talk openly about how physical and emotional intimacy has shifted since the baby arrived.', 'Give a couple language for discussing how intimacy has changed since becoming parents.', array['Couples']::text[], '20 minutes', 'Physical and emotional intimacy often shift substantially after a baby arrives, exhaustion, recovery and a changed sense of self all playing a part, and unspoken assumptions about when or whether things will go back to how they were can create distance. This sheet has both partners describe how intimacy currently feels and what they each need right now, without a deadline attached to any particular change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how intimacy currently feels to me"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need right now"}, {"id": "f2", "type": "textarea", "label": "Partner B: how intimacy currently feels to me"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need right now"}, {"id": "f4", "type": "textarea", "label": "One way we can stay connected while things are in flux"}]'::jsonb, array['perinatal and postpartum', 'couples', 'intimacy']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('new-parent-please-skills-check', 'New Parent PLEASE Skills Check', 'dbt'::resource_kind, 'Rates sleep, food and physical care against the PLEASE skills to flag what is slipping in early parenthood.', 'Help a new parent notice which basic physical needs are slipping during a demanding stretch.', array['Adults']::text[], '10 minutes', 'Early parenthood can make even the most basic physical needs, sleep, food, treating illness, hard to keep up with, and those slips make emotional regulation much harder on top of an already demanding stretch. This check has a client rate each PLEASE area quickly, then pick just one to focus on improving this week rather than trying to fix everything at once.', '[{"id": "f0", "type": "textarea", "label": "My sleep this week, rated 0 to 10"}, {"id": "f1", "type": "textarea", "label": "Whether I have been eating regularly"}, {"id": "f2", "type": "textarea", "label": "Any physical illness or pain I have been pushing through"}, {"id": "f3", "type": "textarea", "label": "Which PLEASE area I am focusing on this week"}, {"id": "f4", "type": "textarea", "label": "One small step to support it"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'regulation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('inner-critic-volume-dial-sheet', 'Inner Critic Volume Dial Sheet', 'worksheet'::resource_kind, 'Has a client rate how loud their inner critic gets across different situations to find a pattern.', 'Help a client map when their inner critic gets loudest instead of treating it as constant.', array['Adults', 'Teens']::text[], '15 minutes', 'A client''s inner critic is rarely equally loud all the time; certain situations, a mistake at work, a comparison with a peer, tend to turn the volume up further than others. This sheet has a client rate the critic''s volume across a handful of situations from the week and look for what those loudest moments have in common. Spotting the pattern gives a specific place to practice a quieter response.', '[{"id": "f0", "type": "textarea", "label": "A situation from this week and the critic''s volume, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "Another situation and its volume"}, {"id": "f2", "type": "textarea", "label": "What the loudest situations have in common"}, {"id": "f3", "type": "textarea", "label": "What the quietest situations have in common"}, {"id": "f4", "type": "textarea", "label": "One thing I want to try in a loud-volume situation"}]'::jsonb, array['self-esteem', 'self-criticism', 'self-monitoring']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('evidence-for-the-whole-self-log', 'Evidence for the Whole Self Log', 'cbt'::resource_kind, 'Logs moments that reflect strengths, effort and values, not just outcomes, to widen self-evaluation.', 'Help a client build evidence for a fuller self-picture beyond performance and outcomes alone.', array['Adults', 'Teens']::text[], 'One week', 'A client''s self-evaluation can narrow down to outcomes only, a grade, a sale, a compliment, while effort, kindness and values-consistent action go unrecorded entirely. This log has a client note one entry each day that reflects something about who they are beyond an outcome, an act of patience, a value they lived by, a moment of honesty. Read the week''s entries back together in session.', '[{"id": "f0", "type": "textarea", "label": "Something I did today that reflects effort, not just outcome"}, {"id": "f1", "type": "textarea", "label": "A value I lived by today, even in a small way"}, {"id": "f2", "type": "textarea", "label": "A strength someone else might have noticed in me today"}, {"id": "f3", "type": "textarea", "label": "How this differs from my usual way of evaluating myself"}, {"id": "f4", "type": "textarea", "label": "What I notice reading the week''s entries together"}]'::jsonb, array['self-esteem', 'core CBT', 'evidence log']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('worthiness-without-conditions-practice', 'Worthiness Without Conditions Practice', 'act'::resource_kind, 'Practices naming a sense of worth that does not depend on achievement, appearance or approval.', 'Help a client explore a sense of worth that holds regardless of external conditions.', array['Adults']::text[], '15 minutes', 'A client''s sense of worth is often quietly conditional, tied to achievement, appearance or others'' approval, without that condition ever being named out loud. This practice has a client name the conditions they have been running on, then explore what an unconditional sense of worth might mean instead, not earned, simply present. This is exploratory work and rarely resolves in a single session.', '[{"id": "f0", "type": "textarea", "label": "A condition I have been placing on my own worth"}, {"id": "f1", "type": "textarea", "label": "Where that condition came from"}, {"id": "f2", "type": "textarea", "label": "What it would mean if worth did not depend on that condition"}, {"id": "f3", "type": "textarea", "label": "A moment this week I practiced acting from unconditional worth"}, {"id": "f4", "type": "textarea", "label": "What came up as I practiced this"}]'::jsonb, array['self-esteem', 'core ACT', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('self-kindness-in-the-mirror-practice', 'Self-Kindness in the Mirror Practice', 'dbt'::resource_kind, 'Pairs a brief mirror moment with a self-validating statement instead of self-criticism.', 'Give a client a brief daily practice of pairing a mirror moment with self-validation instead of critique.', array['Adults', 'Teens']::text[], 'Five minutes', 'A mirror moment often triggers an automatic critique, so this practice has a client pause during one ordinary mirror check each day and pair it with a short self-validating statement instead, something true and kind rather than flattering. Keep the statement simple and specific rather than a big general compliment, since specific statements tend to feel more believable and land better.', '[{"id": "f0", "type": "textarea", "label": "The self-validating statement I used today"}, {"id": "f1", "type": "textarea", "label": "How it felt compared with my usual reaction"}, {"id": "f2", "type": "textarea", "label": "What made it hard to believe, if anything"}, {"id": "f3", "type": "textarea", "label": "A moment today that supports the statement being true"}, {"id": "f4", "type": "textarea", "label": "What I want to say tomorrow"}]'::jsonb, array['self-esteem', 'core DBT', 'self-compassion']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('strength-spotting-bingo', 'Strength Spotting Bingo', 'game'::resource_kind, 'A group fills a bingo card by spotting different strengths in themselves and others during the session.', 'Use a bingo format to help a group notice strengths in themselves and each other.', array['Groups']::text[], '20 minutes', 'Each player gets a bingo card with different strengths listed, patience, creativity, honesty, and marks a square whenever they notice that strength in themselves or a fellow player during the session''s activities. The format turns strength-spotting into something active rather than a static list. Debrief on which strengths were easiest and hardest to notice in oneself.', '[{"id": "f0", "type": "textarea", "label": "A strength I marked in myself"}, {"id": "f1", "type": "textarea", "label": "A strength I marked in someone else"}, {"id": "f2", "type": "textarea", "label": "A strength that was hard for me to claim in myself"}, {"id": "f3", "type": "textarea", "label": "How it felt to have a strength named by someone else"}, {"id": "f4", "type": "textarea", "label": "Whether I got bingo, and on which strengths"}]'::jsonb, array['self-esteem', 'group', 'strengths']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('post-event-replay-interrupt-sheet', 'Post-Event Replay Interrupt Sheet', 'worksheet'::resource_kind, 'Has a client catch a post-event mental replay and redirect to a planned activity instead.', 'Help a client interrupt a mental replay of a social event before it spirals.', array['Adults', 'Teens']::text[], '15 minutes', 'After a social event, a client''s mind can loop back over every moment searching for what went wrong, a process that tends to feed anxiety rather than resolve it. This sheet has a client notice when a replay starts, note it briefly, and redirect to a planned activity instead, kept ready in advance. Reviewing how often replays got interrupted across a week helps build the habit further.', '[{"id": "f0", "type": "textarea", "label": "The event my mind kept replaying"}, {"id": "f1", "type": "textarea", "label": "What I noticed myself searching for in the replay"}, {"id": "f2", "type": "textarea", "label": "The planned activity I redirected to"}, {"id": "f3", "type": "textarea", "label": "How long the replay lasted before I redirected"}, {"id": "f4", "type": "textarea", "label": "What I notice across the week''s attempts"}]'::jsonb, array['social anxiety', 'self-monitoring', 'rumination']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('safety-behavior-reduction-plan', 'Safety Behavior Reduction Plan', 'cbt'::resource_kind, 'Lists small safety behaviors used in social situations and plans to gradually drop them one at a time.', 'Help a client gradually reduce the small safety behaviors that quietly maintain social anxiety.', array['Adults', 'Teens']::text[], 'One week', 'Small safety behaviors, avoiding eye contact, rehearsing every sentence, holding a drink for something to do with your hands, can quietly keep social anxiety in place by preventing a client from learning that the feared outcome would not happen anyway. This plan has a client list their own safety behaviors and choose one to drop in a low-stakes situation first, tracking what actually happens without it.', '[{"id": "f0", "type": "textarea", "label": "A safety behavior I use in social situations"}, {"id": "f1", "type": "textarea", "label": "The situation I am planning to drop it in"}, {"id": "f2", "type": "textarea", "label": "What I predict will happen without it"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "Which safety behavior I want to work on next"}]'::jsonb, array['social anxiety', 'core CBT', 'safety behaviors']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('post-social-skills-debrief-card', 'Post-Social Skills Debrief Card', 'dbt'::resource_kind, 'A short structured debrief for after a social event, balancing what went well with what felt hard.', 'Give a client a balanced way to review a social event instead of only cataloguing what went wrong.', array['Adults', 'Teens']::text[], '10 minutes', 'Without structure, a debrief after a social event tends to become a one-sided list of everything that went wrong, so this card asks for both sides deliberately: one thing that went fine or well, and one thing that felt hard, kept to a fixed short format. Doing this consistently after events helps counter the pull toward an entirely negative recap.', '[{"id": "f0", "type": "textarea", "label": "The event I am debriefing"}, {"id": "f1", "type": "textarea", "label": "One thing that went fine or well"}, {"id": "f2", "type": "textarea", "label": "One thing that felt hard"}, {"id": "f3", "type": "textarea", "label": "A skill I used, if any"}, {"id": "f4", "type": "textarea", "label": "What I want to try at the next event"}]'::jsonb, array['social anxiety', 'core DBT', 'self-monitoring']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('brave-hello-practice-chart', 'Brave Hello Practice Chart', 'kids'::resource_kind, 'A child tracks small brave social moments, like a hello or a question, on a simple chart.', 'Give a socially anxious child a way to notice and build on small brave social moments.', array['Children']::text[], 'One week', 'For a child who finds social moments hard, even a small hello to a classmate can take real courage, and this chart gives them a way to notice and track those small brave moments rather than only measuring themselves against bigger goals like making a new friend. The parent''s role is celebrating the small moment itself, not pushing for a bigger one right away.', '[{"id": "f0", "type": "textarea", "label": "A brave social moment I had today"}, {"id": "f1", "type": "textarea", "label": "How big or small it felt to me"}, {"id": "f2", "type": "textarea", "label": "What helped me do it"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward"}, {"id": "f4", "type": "textarea", "label": "A brave moment I want to try tomorrow"}]'::jsonb, array['social anxiety', 'children', 'exposure']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('would-they-even-notice-game', 'Would They Even Notice Game', 'game'::resource_kind, 'A group compares predicted versus actual audience attention to a small social slip using a quick game format.', 'Use a light group game to test whether others notice a small social slip as much as it feels like they would.', array['Groups', 'Teens']::text[], '20 minutes', 'Socially anxious clients often overestimate how much other people notice or remember a small slip, a stumble over words, a quiet moment, and this game has players predict how much a group would notice a minor scripted slip, then compares that prediction with what group members actually report noticing afterward. The gap between predicted and actual attention is usually the point that lands.', '[{"id": "f0", "type": "textarea", "label": "The slip I predicted others would notice a lot"}, {"id": "f1", "type": "textarea", "label": "What the group actually reported noticing"}, {"id": "f2", "type": "textarea", "label": "How the prediction compared with reality"}, {"id": "f3", "type": "textarea", "label": "A real-life slip of mine I could apply this to"}, {"id": "f4", "type": "textarea", "label": "What I want to remember next time I worry about being noticed"}]'::jsonb, array['social anxiety', 'group', 'thinking traps']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('grief-comes-in-waves-log', 'Grief Comes in Waves Log', 'worksheet'::resource_kind, 'Logs the timing and intensity of grief waves across a week to show they rise and pass rather than build steadily.', 'Help a client see that grief arrives in waves rather than as one steadily building weight.', array['Adults', 'Teens']::text[], 'One week', 'Grief can feel like a single, ever-growing weight, which makes each new wave feel like a setback rather than a normal part of the pattern, so this log has a client note when a wave of grief arrives, how intense it is, and how long it lasts across a week. Looking at the pattern together often shows waves rising and passing rather than one continuous climb, which can be a relief on its own.', '[{"id": "f0", "type": "textarea", "label": "When a wave of grief arrived today"}, {"id": "f1", "type": "textarea", "label": "Its intensity, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How long it lasted"}, {"id": "f3", "type": "textarea", "label": "What was happening right before it arrived"}, {"id": "f4", "type": "textarea", "label": "What I notice about the pattern across the week"}]'::jsonb, array['grief and loss', 'self-monitoring', 'psychoeducation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('carrying-grief-and-living-practice', 'Carrying Grief and Living Practice', 'act'::resource_kind, 'Uses a values-based practice to explore living fully while still actively grieving, not after grief ends.', 'Help a client see that engaging with life and carrying grief can happen at the same time, not in sequence.', array['Adults']::text[], '15 minutes', 'Clients sometimes believe they must finish grieving before they are allowed to laugh, connect or plan again, which can leave life on hold indefinitely. This practice explores carrying grief in one hand and a value, connection, joy, purpose, in the other, at the same time rather than waiting for grief to end first. Notice what comes up when both are held together rather than treated as opposites.', '[{"id": "f0", "type": "textarea", "label": "What I am carrying in the grief hand right now"}, {"id": "f1", "type": "textarea", "label": "A value I want to also hold in the other hand"}, {"id": "f2", "type": "textarea", "label": "What it would look like to hold both at once"}, {"id": "f3", "type": "textarea", "label": "What comes up when I imagine doing that"}, {"id": "f4", "type": "textarea", "label": "One small values-based action I could take this week"}]'::jsonb, array['grief and loss', 'core ACT', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('grieving-on-different-timelines-sheet', 'Grieving on Different Timelines Sheet', 'couples'::resource_kind, 'Helps a couple name how each partner''s grief looks different and what support each actually needs.', 'Give a couple language for the fact that partners often grieve differently and on different timelines.', array['Couples']::text[], '20 minutes', 'Partners grieving the same loss often move through it differently, one wanting to talk, the other wanting quiet, one ready to laugh again sooner than the other, and without a shared understanding this difference can feel like a lack of care rather than simply a difference. This sheet has each partner describe their own grief and what support actually helps, so neither has to guess or feel judged for grieving differently.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what my grief tends to look like"}, {"id": "f1", "type": "textarea", "label": "Partner A: what actually helps me right now"}, {"id": "f2", "type": "textarea", "label": "Partner B: what my grief tends to look like"}, {"id": "f3", "type": "textarea", "label": "Partner B: what actually helps me right now"}, {"id": "f4", "type": "textarea", "label": "What we want to understand about each other''s timeline"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('remembering-together-drawing', 'Remembering Together Drawing', 'kids'::resource_kind, 'A child and parent draw a memory of the person or pet who died to make space for remembering.', 'Give a child a gentle, concrete way to hold onto a memory of someone or something they lost.', array['Children']::text[], '20 minutes', 'A young child may not have words ready for a loss, and this activity gives them a concrete way in instead: drawing a favorite memory together with the parent, talking about it as they draw. Let the child lead how much or little they want to say. Keep the drawing somewhere the child can return to when they want to remember again.', '[{"id": "f0", "type": "textarea", "label": "The memory I drew"}, {"id": "f1", "type": "textarea", "label": "What I remember most about it"}, {"id": "f2", "type": "textarea", "label": "A feeling I had while drawing it"}, {"id": "f3", "type": "textarea", "label": "Who I want to show my drawing to"}, {"id": "f4", "type": "textarea", "label": "Something I want to remember always"}]'::jsonb, array['grief and loss', 'children', 'memory']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('grief-question-jar-game', 'Grief Question Jar Game', 'game'::resource_kind, 'A group draws gentle open-ended questions about loss from a jar to spark conversation at their own pace.', 'Give a grief group a low-pressure way to open conversation about loss at each person''s own pace.', array['Groups', 'Teens']::text[], '20 minutes', 'Talking directly about a loss can feel too exposed for some group members, so this game has players draw a gentle open-ended question from a jar, such as what they miss most or a tradition connected to the person, and answer only as much as feels comfortable. Passing is always allowed. The structure gives quieter members an entry point without forcing anyone to share more than they choose.', '[{"id": "f0", "type": "textarea", "label": "The question I drew from the jar"}, {"id": "f1", "type": "textarea", "label": "As much as I chose to share about it"}, {"id": "f2", "type": "textarea", "label": "A question another group member drew that stayed with me"}, {"id": "f3", "type": "textarea", "label": "How it felt to have the choice to pass"}, {"id": "f4", "type": "textarea", "label": "What I want to remember from today''s group"}]'::jsonb, array['grief and loss', 'group', 'disclosure']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('bids-for-connection-tracking-sheet', 'Bids for Connection Tracking Sheet', 'couples'::resource_kind, 'Has both partners notice and log small bids for attention and how often each is turned toward.', 'Help a couple notice how often small bids for connection are turned toward versus missed.', array['Couples']::text[], 'One week', 'A bid for connection can be as small as a comment about the weather or a glance across the room, and whether it gets turned toward, turned away from, or missed entirely tends to add up over time far more than any single big gesture. This sheet has both partners log a few bids they made or noticed each day and whether they were turned toward. Reviewing the week together usually surfaces small, fixable patterns.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a bid I made and what happened"}, {"id": "f1", "type": "textarea", "label": "Partner A: a bid I noticed from my partner and how I responded"}, {"id": "f2", "type": "textarea", "label": "Partner B: a bid I made and what happened"}, {"id": "f3", "type": "textarea", "label": "Partner B: a bid I noticed from my partner and how I responded"}, {"id": "f4", "type": "textarea", "label": "What we want to try turning toward more this week"}]'::jsonb, array['relationship issues', 'couples', 'connection']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('unspoken-rules-of-the-relationship-sheet', 'Unspoken Rules of the Relationship Sheet', 'couples'::resource_kind, 'Surfaces the unstated rules each partner has been operating on to check whether both actually agree to them.', 'Help a couple name the unspoken rules quietly running their relationship and decide together whether to keep them.', array['Couples']::text[], '20 minutes', 'Every relationship accumulates unspoken rules over time, who initiates plans, who apologizes first, what topics are off-limits, and partners often follow them without ever agreeing to them out loud. This sheet has each partner name a few rules they have noticed themselves following, then discuss together which ones both actually want to keep. Some surprise both partners once said out loud.', '[{"id": "f0", "type": "textarea", "label": "Partner A: an unspoken rule I have noticed myself following"}, {"id": "f1", "type": "textarea", "label": "Partner A: whether I actually want to keep it"}, {"id": "f2", "type": "textarea", "label": "Partner B: an unspoken rule I have noticed myself following"}, {"id": "f3", "type": "textarea", "label": "Partner B: whether I actually want to keep it"}, {"id": "f4", "type": "textarea", "label": "One rule we are agreeing to change or drop"}]'::jsonb, array['relationship issues', 'couples', 'communication']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('relationship-thought-trap-spotter', 'Relationship Thought Trap Spotter', 'cbt'::resource_kind, 'Has a client catch a thinking trap specifically about their relationship, like mind reading a partner''s intent.', 'Help a client notice thinking traps that specifically distort how they read their partner''s behavior.', array['Adults']::text[], '15 minutes', 'Thinking traps show up in relationships just as they do elsewhere, assuming a partner''s silence means anger, or that one late reply means the relationship is failing, and these traps can drive a reaction before the client ever checks the facts. This sheet has a client catch a relationship-specific trap, name it, and consider a more balanced reading of the same behavior. Bring a few examples back to session.', '[{"id": "f0", "type": "textarea", "label": "What my partner did or said"}, {"id": "f1", "type": "textarea", "label": "What I assumed it meant"}, {"id": "f2", "type": "textarea", "label": "The thinking trap I notice in that assumption"}, {"id": "f3", "type": "textarea", "label": "A more balanced reading of the same behavior"}, {"id": "f4", "type": "textarea", "label": "How I could check instead of assume"}]'::jsonb, array['relationship issues', 'core CBT', 'thinking traps']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('relationship-willingness-practice', 'Relationship Willingness Practice', 'act'::resource_kind, 'Helps a client identify one values-based action toward a partner they can take despite current hurt or resentment.', 'Help a client act on relationship values even while hurt or resentment is still present.', array['Adults']::text[], '15 minutes', 'Waiting for hurt or resentment to fully clear before acting warmly toward a partner can mean waiting a long time, so this practice has a client identify one small values-based action, patience, warmth, honesty, they are willing to take even while the difficult feeling is still present. This is not about suppressing the feeling, only about not letting it be the only thing that decides the next action.', '[{"id": "f0", "type": "textarea", "label": "The hurt or resentment currently present for me"}, {"id": "f1", "type": "textarea", "label": "A value I want to act on with my partner anyway"}, {"id": "f2", "type": "textarea", "label": "One small action that would express it"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "What it was like to act despite the feeling still being there"}]'::jsonb, array['relationship issues', 'core ACT', 'values']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('relationship-distress-tolerance-menu', 'Relationship Distress Tolerance Menu', 'dbt'::resource_kind, 'A menu of skills a client can use to tolerate a hard relationship moment without acting impulsively.', 'Give a client a menu of skills to reach for during a hard relationship moment instead of an impulsive reaction.', array['Adults']::text[], '10 minutes', 'A hard moment in a relationship, a hurtful comment, a broken plan, can trigger an impulsive reaction that makes things worse before the client has had a chance to think, so this menu offers a few distress tolerance options to reach for first: a short walk, paced breathing, or naming the urge out loud before acting on it. The goal is buying time, not suppressing the feeling.', '[{"id": "f0", "type": "textarea", "label": "The hard moment I am working through"}, {"id": "f1", "type": "textarea", "label": "The skill I reached for first"}, {"id": "f2", "type": "textarea", "label": "What the urge to react impulsively was telling me to do"}, {"id": "f3", "type": "textarea", "label": "What I did instead"}, {"id": "f4", "type": "textarea", "label": "How the moment looked once I had bought some time"}]'::jsonb, array['relationship issues', 'distress tolerance', 'core DBT']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('safe-adults-and-safe-spaces-map', 'Safe Adults and Safe Spaces Map', 'worksheet'::resource_kind, 'Has a client map current safe people and places to build a felt sense of safety in the present.', 'Help a client build a concrete, present-day map of safety rather than dwelling in the past.', array['Adults', 'Teens']::text[], '20 minutes', 'A client working through the aftermath of sexual abuse benefits from a strong, concrete sense of who and where feels safe right now, separate from anything about what happened. This sheet has them map current safe people, places and objects, building a resource they can return to whenever grounding is needed. It is intentionally forward-facing and does not ask for any account of the past.', '[{"id": "f0", "type": "textarea", "label": "A person who feels safe to me right now"}, {"id": "f1", "type": "textarea", "label": "A place that feels safe to me right now"}, {"id": "f2", "type": "textarea", "label": "An object or routine that helps me feel grounded"}, {"id": "f3", "type": "textarea", "label": "How I can reach one of these when I need to"}, {"id": "f4", "type": "textarea", "label": "What safety feels like in my body right now"}]'::jsonb, array['sexual abuse', 'safety', 'grounding']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('present-day-body-ownership-sheet', 'Present-Day Body Ownership Sheet', 'cbt'::resource_kind, 'Has a client name current choices they hold over their own body to build a present-tense sense of ownership.', 'Help a client build present-day evidence of choice and ownership over their own body.', array['Adults', 'Teens']::text[], '15 minutes', 'Reclaiming a felt sense of ownership over one''s own body can be a slow, present-focused process, and this sheet supports it by having a client name small choices they currently hold, what to wear, who to be touched by, how to move through their day, and notice each one as an exercise of that ownership. This stays entirely in the present and does not ask about the past.', '[{"id": "f0", "type": "textarea", "label": "A choice about my body I made today"}, {"id": "f1", "type": "textarea", "label": "How it felt to notice that as my own choice"}, {"id": "f2", "type": "textarea", "label": "A boundary I held today"}, {"id": "f3", "type": "textarea", "label": "What supported me in holding it"}, {"id": "f4", "type": "textarea", "label": "What ownership over my body feels like right now"}]'::jsonb, array['sexual abuse', 'core CBT', 'safety']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('compassion-toward-the-body-practice', 'Compassion Toward the Body Practice', 'act'::resource_kind, 'A gentle acceptance-based practice for extending compassion toward a body that has been through harm.', 'Support a client in extending compassion toward their body rather than treating it as separate or at fault.', array['Adults']::text[], '15 minutes', 'Sexual abuse can leave a client relating to their own body with distance or blame, as though it were separate from them or somehow responsible, and this practice offers a slow, gentle way to extend compassion toward the body instead, a hand placed gently, a few kind words directed inward. Go at whatever pace feels tolerable and stop if it becomes too activating; this is stabilizing work, not exposure work.', '[{"id": "f0", "type": "textarea", "label": "What it was like to bring compassion toward my body"}, {"id": "f1", "type": "textarea", "label": "Where I noticed resistance, if any"}, {"id": "f2", "type": "textarea", "label": "A kind word or phrase that felt true"}, {"id": "f3", "type": "textarea", "label": "How my body felt afterward"}, {"id": "f4", "type": "textarea", "label": "What I want to try again next time"}]'::jsonb, array['sexual abuse', 'core ACT', 'self-compassion']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('grounding-through-pacing-card', 'Grounding Through Pacing Card', 'dbt'::resource_kind, 'A pocket card for pacing grounding skills so a client does not feel rushed through the process.', 'Give a client control over the pace of their own grounding practice.', array['Adults', 'Teens']::text[], '10 minutes', 'Being rushed through anything, including a coping skill, can itself feel unsafe for a client recovering from abuse, so this card is built around pacing: a menu of grounding options with permission to move as slowly as needed and to stop at any point. Complete this in session first, and let the client set the pace and choose which options to keep. 988 can be called or texted anytime support is needed between sessions.', '[{"id": "f0", "type": "textarea", "label": "The grounding option I chose to start with"}, {"id": "f1", "type": "textarea", "label": "How the pace felt, too fast, too slow, or right"}, {"id": "f2", "type": "textarea", "label": "Where I chose to stop or pause"}, {"id": "f3", "type": "textarea", "label": "What helped me feel most in control of the pace"}, {"id": "f4", "type": "textarea", "label": "What I want on my own version of this card"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'pacing']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('partner-patience-and-pacing-agreement', 'Partner Patience and Pacing Agreement', 'couples'::resource_kind, 'Has both partners agree on pacing around touch and closeness while one partner is healing.', 'Give a couple a shared, explicit agreement about pacing physical closeness during healing.', array['Couples']::text[], '20 minutes', 'A partner supporting someone healing from sexual abuse often wants to help but is unsure what is welcome, and guessing wrong can cause real hurt on both sides, so this sheet has both partners talk openly about pacing: what kinds of touch feel safe right now, what does not, and how to check in without it feeling like a test. Revisit the agreement as things shift, since pacing that works today may change.', '[{"id": "f0", "type": "textarea", "label": "Partner healing: what feels safe to me right now"}, {"id": "f1", "type": "textarea", "label": "Partner healing: what does not feel safe right now"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: how I will check in before touch"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what I need in order to keep checking in without frustration"}, {"id": "f4", "type": "textarea", "label": "How we will revisit this agreement as things change"}]'::jsonb, array['sexual abuse', 'couples', 'pacing']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('situation-matched-coping-card-sort', 'Situation-Matched Coping Card Sort', 'worksheet'::resource_kind, 'Sorts a client''s existing coping skills by which type of situation each one actually fits best.', 'Help a client match the right coping skill to the right kind of situation instead of using one skill for everything.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients often default to one familiar coping skill regardless of the situation, even when it is not the best fit, a calming skill used when what is actually needed is problem-solving, or vice versa. This sort has a client write out their coping skills on cards and sort them by situation type: needs calming, needs distraction, needs a decision. Use the sorted set to plan ahead for likely upcoming situations.', '[{"id": "f0", "type": "textarea", "label": "A coping skill I use often"}, {"id": "f1", "type": "textarea", "label": "The type of situation it actually fits best"}, {"id": "f2", "type": "textarea", "label": "A situation where I used the wrong-fit skill by habit"}, {"id": "f3", "type": "textarea", "label": "A better-fitting skill for that situation"}, {"id": "f4", "type": "textarea", "label": "My sorted list by situation type"}]'::jsonb, array['coping skills', 'self-monitoring', 'planning']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('coping-skill-barrier-troubleshoot-sheet', 'Coping Skill Barrier Troubleshoot Sheet', 'cbt'::resource_kind, 'Identifies what specifically gets in the way of using a known coping skill in the moment it is needed.', 'Help a client troubleshoot why a known coping skill does not get used when it is actually needed.', array['Adults', 'Teens']::text[], '15 minutes', 'A client often knows a coping skill well in theory but still does not reach for it in the moment it is needed, and this sheet digs into why: too complicated to remember, feels silly, not physically available, forgotten in the moment. Naming the specific barrier makes it possible to solve, whether that means simplifying the skill or building a reminder into the environment.', '[{"id": "f0", "type": "textarea", "label": "The coping skill I know but do not use enough"}, {"id": "f1", "type": "textarea", "label": "What specifically gets in the way of using it"}, {"id": "f2", "type": "textarea", "label": "A way to make it simpler or more available"}, {"id": "f3", "type": "textarea", "label": "A reminder I could build into my day"}, {"id": "f4", "type": "textarea", "label": "What I want to try this week"}]'::jsonb, array['coping skills', 'core CBT', 'self-monitoring']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('coping-skills-as-acts-of-care-practice', 'Coping Skills as Acts of Care Practice', 'act'::resource_kind, 'Reframes coping skills as an expression of self-care values rather than a fix for a problem.', 'Help a client experience coping skills as an act of care toward themselves rather than a chore.', array['Adults']::text[], '15 minutes', 'Coping skills can start to feel like homework, one more task on a list, which paradoxically makes them harder to reach for, so this practice reframes each skill as an act of care a client is choosing to offer themselves, the same way they might offer it to someone they love. Pick one skill and practice it deliberately from that frame rather than from obligation, and notice whether it feels different.', '[{"id": "f0", "type": "textarea", "label": "The coping skill I practiced from a place of care"}, {"id": "f1", "type": "textarea", "label": "What it felt like to frame it that way"}, {"id": "f2", "type": "textarea", "label": "How this compared with doing it out of obligation"}, {"id": "f3", "type": "textarea", "label": "A value this act of care connects to"}, {"id": "f4", "type": "textarea", "label": "What I want to bring this frame to next"}]'::jsonb, array['coping skills', 'core ACT', 'self-compassion']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('coping-recipe-steps-craft', 'Coping Recipe Steps Craft', 'kids'::resource_kind, 'A child writes their own coping skill as a step-by-step recipe card to make it easy to follow.', 'Give a child an easy-to-follow, personalized recipe for calming down.', array['Children']::text[], '20 minutes', 'Framing a coping skill as a recipe, with clear steps and a picture of the finished result, a calmer feeling, gives a young child something familiar and concrete to follow instead of an abstract instruction to calm down. The parent and child write the steps together and decorate the card like an actual recipe. Keep it somewhere the child can grab it when needed.', '[{"id": "f0", "type": "textarea", "label": "Step one of my calm-down recipe"}, {"id": "f1", "type": "textarea", "label": "Step two of my calm-down recipe"}, {"id": "f2", "type": "textarea", "label": "What the finished result feels like"}, {"id": "f3", "type": "textarea", "label": "A time I used my recipe"}, {"id": "f4", "type": "textarea", "label": "What I want to change about the recipe"}]'::jsonb, array['coping skills', 'children', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('coping-skill-charades-game', 'Coping Skill Charades Game', 'game'::resource_kind, 'Players act out a coping skill without speaking for the group to guess, followed by a real-life discussion.', 'Use charades to make learning and remembering coping skills active and fun for a group.', array['Groups', 'Children']::text[], '20 minutes', 'A player draws a coping skill card and acts it out silently, deep breathing, counting, a favorite stretch, while the group guesses which skill it is, then the group briefly discusses when that skill might actually be useful for them. Acting the skill out physically tends to help it stick better than simply reading a list. Keep the pace playful and celebrate creative acting attempts.', '[{"id": "f0", "type": "textarea", "label": "The skill I acted out"}, {"id": "f1", "type": "textarea", "label": "A skill I guessed correctly"}, {"id": "f2", "type": "textarea", "label": "A skill that was fun or funny to act out"}, {"id": "f3", "type": "textarea", "label": "When I might actually use one of the skills from the game"}, {"id": "f4", "type": "textarea", "label": "A skill I want to remember most"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('feared-object-fact-file-sheet', 'Feared Object Fact File Sheet', 'worksheet'::resource_kind, 'Has a client research and record plain facts about a feared object or situation to sit alongside the fear.', 'Give a client a factual counterweight to sit alongside an exaggerated feared image.', array['Adults', 'Teens']::text[], '15 minutes', 'A phobia often runs on an exaggerated mental image of the feared object or situation, and this sheet has a client build a simple fact file, plain, verifiable information, to sit alongside that image rather than replace it outright. The point is not to argue the fear away but to give the client a second, factual reference point available when the exaggerated image takes over.', '[{"id": "f0", "type": "textarea", "label": "The feared object or situation"}, {"id": "f1", "type": "textarea", "label": "A fact I found about it"}, {"id": "f2", "type": "textarea", "label": "Another fact I found"}, {"id": "f3", "type": "textarea", "label": "How the exaggerated image compares with the facts"}, {"id": "f4", "type": "textarea", "label": "What I want to remember when the fear spikes"}]'::jsonb, array['phobias', 'self-monitoring', 'psychoeducation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('micro-exposure-ladder-builder', 'Micro-Exposure Ladder Builder', 'cbt'::resource_kind, 'Builds an exposure ladder with steps small enough that the first one feels almost too easy.', 'Help a client build a graded exposure ladder starting from a step that feels genuinely manageable.', array['Adults', 'Teens']::text[], '20 minutes', 'A ladder with its first rung set too high often stalls before it starts, so this builder deliberately aims for a first step small enough to feel almost too easy, then works upward from there. A client lists the full range of situations connected to the fear, rates each for difficulty, and orders them into a ladder. Move up only once a rung feels manageable, not simply tolerable.', '[{"id": "f0", "type": "textarea", "label": "The fear this ladder is built around"}, {"id": "f1", "type": "textarea", "label": "My first, easiest step"}, {"id": "f2", "type": "textarea", "label": "The next few steps in order of difficulty"}, {"id": "f3", "type": "textarea", "label": "The hardest step at the top"}, {"id": "f4", "type": "textarea", "label": "Which step I am ready to try next"}]'::jsonb, array['phobias', 'core CBT', 'exposure']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-for-exposure-card', 'Distress Tolerance for Exposure Card', 'dbt'::resource_kind, 'A pocket card of skills to use during an exposure step to stay with the discomfort rather than escape it.', 'Give a client skills to stay present through an exposure step rather than leaving early.', array['Adults', 'Teens']::text[], '10 minutes', 'Leaving an exposure step early because the discomfort feels unbearable can reinforce the fear rather than reduce it, so this card offers a short menu of distress tolerance skills, paced breathing, brief grounding, a coping statement, to help a client stay in the step a bit longer. The goal is staying with discomfort long enough for it to shift, not eliminating it.', '[{"id": "f0", "type": "textarea", "label": "The exposure step I am working on"}, {"id": "f1", "type": "textarea", "label": "The skill I used to stay with it"}, {"id": "f2", "type": "textarea", "label": "Distress level at the start, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Distress level after staying with it"}, {"id": "f4", "type": "textarea", "label": "Whether I stayed as long as planned"}]'::jsonb, array['phobias', 'distress tolerance', 'exposure']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('partner-cheerleader-not-rescuer-sheet', 'Partner Cheerleader Not Rescuer Sheet', 'couples'::resource_kind, 'Helps a supporting partner learn to encourage an exposure step rather than step in to rescue from it.', 'Help a supporting partner learn to encourage rather than rescue during a phobia exposure step.', array['Couples']::text[], '20 minutes', 'A supporting partner''s instinct to protect can accidentally undercut an exposure step, stepping in to handle the feared thing before the client gets the chance to face it themselves. This sheet has both partners agree on what genuine encouragement looks like versus rescuing, and what signal the client can give if they truly do need the partner to step in. Practice the signal in advance.', '[{"id": "f0", "type": "textarea", "label": "Partner facing the fear: what encouragement, not rescue, looks like to me"}, {"id": "f1", "type": "textarea", "label": "Partner facing the fear: my signal for if I truly need help"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what I will say instead of stepping in"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what makes it hard not to rescue"}, {"id": "f4", "type": "textarea", "label": "One agreement we are making about the next exposure step"}]'::jsonb, array['phobias', 'couples', 'exposure']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('fear-ladder-board-game', 'Fear Ladder Board Game', 'game'::resource_kind, 'Players move a token up a drawn ladder board as they answer prompts about facing small fears.', 'Use a simple board game to make talking about facing fears feel playful rather than heavy.', array['Groups', 'Children']::text[], '20 minutes', 'Players move a token up a drawn ladder by answering a prompt each turn, naming a fear, a step that would face it, or a time they were brave, with each correct or honest answer moving the token up one rung. Keep it light and let players choose how much detail to share. Whoever''s token reaches the top first can cheer the rest of the group up the ladder too.', '[{"id": "f0", "type": "textarea", "label": "A prompt I answered during the game"}, {"id": "f1", "type": "textarea", "label": "A fear I named"}, {"id": "f2", "type": "textarea", "label": "A step that would help face it"}, {"id": "f3", "type": "textarea", "label": "A time I was brave that I remembered during the game"}, {"id": "f4", "type": "textarea", "label": "How far my token climbed"}]'::jsonb, array['phobias', 'group', 'play']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('appearance-talk-awareness-sheet', 'Appearance Talk Awareness Sheet', 'cbt'::resource_kind, 'Logs how often a client talks about appearance, their own or others'', to see how much airtime it takes up.', 'Help a client see how much daily conversation and thought is going toward appearance.', array['Adults', 'Teens']::text[], 'One week', 'Comments about appearance, one''s own or someone else''s, can become so routine they go unnoticed, quietly reinforcing how much attention the body''s look receives relative to everything else. This sheet has a client log each appearance comment they make or hear across a week, then reflect on what that adds up to. The goal is awareness, not guilt about any single comment.', '[{"id": "f0", "type": "textarea", "label": "An appearance comment I made or heard today"}, {"id": "f1", "type": "textarea", "label": "Whether it was about my own appearance or someone else''s"}, {"id": "f2", "type": "textarea", "label": "How I felt saying or hearing it"}, {"id": "f3", "type": "textarea", "label": "A non-appearance comment I could offer instead next time"}, {"id": "f4", "type": "textarea", "label": "What I notice about the week''s total"}]'::jsonb, array['body image', 'self-monitoring', 'core CBT']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('function-over-appearance-practice', 'Function Over Appearance Practice', 'act'::resource_kind, 'Practices describing the body by what it does across a day rather than how it looks.', 'Help a client build the habit of noticing their body by function rather than appearance.', array['Adults', 'Teens']::text[], '15 minutes', 'Body image work often benefits from practicing an entirely different lens on the body, one built around function rather than appearance, and this practice has a client narrate their body''s actions across an ordinary day, carrying groceries, laughing, climbing stairs, without any reference to how it looked doing so. Repetition matters more than any single entry; the lens takes practice to hold.', '[{"id": "f0", "type": "textarea", "label": "Something my body did for me today"}, {"id": "f1", "type": "textarea", "label": "Another thing my body did for me today"}, {"id": "f2", "type": "textarea", "label": "How it felt to describe my body this way"}, {"id": "f3", "type": "textarea", "label": "A moment I noticed myself slipping back to appearance language"}, {"id": "f4", "type": "textarea", "label": "What I want to notice more of tomorrow"}]'::jsonb, array['body image', 'core ACT', 'self-compassion']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-body-scan-practice', 'Nonjudgmental Body Scan Practice', 'dbt'::resource_kind, 'A brief mindfulness body scan practiced with nonjudgmental, descriptive language only.', 'Give a client practice noticing the body with neutral, descriptive attention instead of evaluation.', array['Adults', 'Teens']::text[], '10 minutes', 'A body scan practiced with strictly descriptive language, noticing warmth, tension or ease without labeling any of it good or bad, gives a client a different way of relating to their own body than the evaluative lens they usually bring. Guide the scan slowly through a few body areas, redirecting gently back to description any time a judgment slips in. This is a mindfulness skill, not a body-checking exercise.', '[{"id": "f0", "type": "textarea", "label": "What I noticed in my body during the scan, described neutrally"}, {"id": "f1", "type": "textarea", "label": "A moment a judgment slipped in"}, {"id": "f2", "type": "textarea", "label": "How I redirected back to description"}, {"id": "f3", "type": "textarea", "label": "How this scan compared with how I usually relate to my body"}, {"id": "f4", "type": "textarea", "label": "What I want to practice noticing next time"}]'::jsonb, array['body image', 'mindfulness', 'core DBT']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('my-body-s-superpowers-drawing', 'My Body''s Superpowers Drawing', 'kids'::resource_kind, 'A child draws their body as having superpowers based on what it can do, not how it looks.', 'Help a child build an early function-focused, playful relationship with their own body.', array['Children']::text[], '20 minutes', 'Framing the body''s abilities as superpowers, running fast, hugging tight, climbing high, gives a young child a playful, function-focused way to think about their own body well before appearance-focused messages take hold more strongly. The parent and child draw the child as a superhero with powers based on real things the body can do. Keep the conversation led by what the child brings up.', '[{"id": "f0", "type": "textarea", "label": "A superpower my body has"}, {"id": "f1", "type": "textarea", "label": "Another superpower my body has"}, {"id": "f2", "type": "textarea", "label": "How I drew myself using my superpowers"}, {"id": "f3", "type": "textarea", "label": "How my body helped me today"}, {"id": "f4", "type": "textarea", "label": "My favorite thing my body lets me do"}]'::jsonb, array['body image', 'children', 'art']::text[], '2026-09-28T15:00:00+00:00'::timestamptz),
  ('media-message-spot-the-trick-game', 'Media Message Spot the Trick Game', 'game'::resource_kind, 'A group spots editing and marketing tricks in sample images to build media literacy around appearance.', 'Use a group activity to build critical media literacy around appearance-focused images.', array['Groups', 'Teens']::text[], '20 minutes', 'Players look at a set of sample images and try to spot the tricks used to shape how bodies appear, lighting, angles, editing, posing, earning a point for each trick correctly identified. The game builds a habit of critical viewing that can carry over to everyday media, gently loosening the pull of comparison. Debrief on how it felt to look at the images differently once the tricks were visible.', '[{"id": "f0", "type": "textarea", "label": "A trick I spotted in one of the images"}, {"id": "f1", "type": "textarea", "label": "How the image looked different once I saw the trick"}, {"id": "f2", "type": "textarea", "label": "A trick I want to look for in media on my own now"}, {"id": "f3", "type": "textarea", "label": "How many points I earned"}, {"id": "f4", "type": "textarea", "label": "What I want to remember next time I compare myself to an image"}]'::jsonb, array['body image', 'group', 'psychoeducation']::text[], '2026-09-28T15:00:00+00:00'::timestamptz)
